/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A46 checkpoint staging; frozen manifest hit–honorable, 80 lemmas. */
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,a,b,c,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(s,domain,en,zh,structure,grammar,rationale)=>({senseId:s,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs});
P('hit','Hit 的早期来源尚有争议；英语中已长期用于“击打”，现代也可表示碰撞、遭遇困难、突然想到以及受欢迎的作品。',C('hit.s4','灵感与思考','While washing dishes, an idea hit Mara: the empty courtyard could become a community garden.','洗碗时，玛拉突然想到一个主意：空院子可以改成社区花园。','While washing dishes / an idea hit Mara / the empty courtyard could become a community garden.','idea hit sb 表示某个想法突然进入某人脑中。','她在日常活动中突然想到方案，符合 s4。'),M('The idea hit Mara gradually after she planned it for several months.','The idea suddenly hit Mara while she was washing dishes.','hit 表示念头突然出现；预先计划数月不符合突然想到。'),[Q('hit',1,1,'The bat hit the ball means it?','struck the ball with force','carried the ball home','measured the ball’s weight','hit 可指用力击打。'),Q('hit',2,2,'The car hit a barrier means it?','crashed into the barrier','avoided the barrier completely','built a barrier on the road','hit 可指撞上物体。'),Q('hit',3,3,'When a recession hits a town, it?','affects the town badly','visits the town as a tourist','repairs its roads','灾害或困难 hit 指侵袭、影响。'),Q('hit',4,5,'A hit song is one that?','is very popular or successful','has never been heard by anyone','is always played too quietly','hit 作名词也指成功之作。')]);
P('hit back','Hit back 是 hit 与 back 构成的短语动词，指遭到攻击或批评后进行回击，也可比喻反驳。',C('hit back.s1','冲突应对','After the rival team shoved him, Leon hit back once and then stepped away when the referee intervened.','对手球队推了他之后，利昂回击了一下；裁判介入时他便退开了。','After the rival team shoved him / Leon hit back once / and then stepped away when the referee intervened.','hit back 表示受到攻击后回击；once 限定次数。','先被推后回击，清楚体现反击。'),M('The player hit back by quietly accepting the insult and making no response.','The player hit back by answering the insult with a firm reply.','不回应辱骂与回击相反。'),[Q('hit back',1,1,'If a boxer hits back, the boxer?','strikes in response to being attacked','leaves the ring before the match','asks the referee to count the audience','hit back 表示回击。'),Q('hit back',2,1,'A politician hit back at a critic by?','answering the criticism forcefully','agreeing silently with every claim','changing the topic to lunch','比喻义是有力反驳。'),Q('hit back',3,1,'What usually comes before someone hits back?','an attack or criticism','a peaceful compliment only','a weather forecast','回击通常是对先前攻击的反应。'),Q('hit back',4,1,'Which phrase is closest to hit back in an argument?','reply sharply to the attack','withdraw without answering','repeat the other person’s words','争论中 hit back 指反驳。')]);
P('hitch','Hitch 的词源并不确定；作动词可指拴、系或搭便车，名词可指免费搭乘，也可指小故障或障碍。',C('hitch.s1','旅途与意外','Our trip went smoothly until a flat tire caused a small hitch on the mountain road.','旅程原本很顺利，直到山路上的爆胎造成一个小麻烦。','Our trip went smoothly / until a flat tire caused a small hitch / on the mountain road.','hitch 作名词可指小故障；until 引出顺利进程中的阻碍。','爆胎是旅程中的小故障，符合此义。'),M('The trip had no hitch at all because the engine failed and the car could not move.','The trip had a hitch when the engine failed and delayed us.','发动机故障并造成延误，不能说旅程毫无问题。'),[Q('hitch',1,1,'A hitch in a plan is a?','small problem or snag','final reward for finishing it','place where a plane lands','hitch 名词可指小障碍。'),Q('hitch',2,1,'To hitch a ride is to?','get a free lift in someone else’s vehicle','rent a car for a full week','repair the vehicle’s engine','hitch a ride 指搭便车。'),Q('hitch',3,1,'A hitch in the schedule might?','delay the event slightly','guarantee it starts early','turn it into a different sport','小故障可能导致轻微延误。'),Q('hitch',4,1,'Which sentence uses hitch as a verb?','She hitched her backpack to the rail.','She repaired the hitch in the timetable.','She bought a ticket for the train.','hitch 作动词可指拴系、挂上。')]);
P('hitchhike','Hitchhike 是20世纪美国英语中由 hitch a ride 与 hike 组合形成的动词，指站在路边请求司机免费搭载旅行。',C('hitchhike.s1','低预算旅行','Because the last bus had left, the students decided to hitchhike to the next town, standing where cars could safely pull over.','末班车已经开走，学生们决定搭便车去下一个镇，并站在汽车可安全停靠的地方。','Because the last bus had left / the students decided to hitchhike / to the next town / standing where cars could safely pull over.','hitchhike 是不及物动词，表示请求搭乘他人车辆旅行。','站在路边等司机免费搭载正是 hitchhike。'),M('They hitchhiked by buying a reserved seat on the express train.','They hitchhiked by asking passing drivers for a free lift.','购买火车票不是向司机请求免费搭乘。'),[Q('hitchhike',1,1,'To hitchhike is to travel by?','asking drivers for a free ride','booking a luxury hotel room','walking only on a treadmill','hitchhike 指搭便车旅行。'),Q('hitchhike',2,1,'Where does a person usually hitchhike?','beside a road where drivers can stop safely','in the middle of a closed runway','inside a locked train carriage','搭便车者通常在路边等车辆。'),Q('hitchhike',3,1,'A hitchhiker hopes that a driver will?','offer them a lift without a fare','sell them a bicycle','repair the road ahead','hitchhike 依靠司机提供免费搭乘。'),Q('hitchhike',4,1,'Which is not hitchhiking?','paying for a booked coach ticket','asking a passing motorist for a lift','standing at a safe roadside pickup point','购买预订车票不是搭便车。')]);
P('hither','Hither 源自古英语 hider，意为“到这边、到这里”，如今多见于诗歌、古风表达或固定短语。',C('hither.s1','文学与方向','The guide called, “Come hither,” and pointed toward the stone archway beside the river.','向导喊道：“到这边来。”并指向河边的石拱门。','The guide called / “Come hither” / and pointed toward the stone archway beside the river.','hither 是表示朝向说话者位置的古雅副词。','指向近处并招呼对方过来，体现“到这里”。'),M('The guide said “come hither” while pointing travelers away from the speaker and toward the distant mountains.','The guide said “come hither” while pointing toward the nearby archway.','hither 表示朝说话者这里，不是远离说话者的方向。'),[Q('hither',1,1,'The old-fashioned word hither means?','to this place or toward the speaker','away from this place','at a time next year','hither 表示到这里。'),Q('hither',2,1,'“Come hither” is an instruction to?','approach the person speaking','leave the room at once','wait until tomorrow','come hither 即到说话者这边来。'),Q('hither',3,1,'Where might a reader encounter hither?','in an old poem or formal tale','in a modern traffic sign only','in a list of chemical elements','hither 带有古雅或文学色彩。'),Q('hither',4,1,'Which is the closest modern wording for hither?','come here','go away','not yet','hither 最接近 here。')]);
P('hitherto','Hitherto 由古英语 hider 与 to 组合而来，表示直到现在或某个指定时点为止，也可指此前的情况。',C('hitherto.s1','研究进展','Hitherto, the team had tested the coating only in dry weather, so the new rain trial filled an important gap.','到那时为止，团队只在干燥天气测试过涂层，因此新的雨天试验填补了重要空白。','Hitherto / the team had tested the coating only in dry weather / so the new rain trial filled an important gap.','hitherto 作句首副词，概括到指定时点以前的状况。','新试验之前只测过晴天，体现“此前为止”。'),M('Hitherto means from now onward, so it describes a plan that will begin next year.','Hitherto means up to that time, before the next year’s plan begins.','hitherto 指截至某个时点以前，不表示未来开始。'),[Q('hitherto',1,1,'Hitherto, the project has used local materials means?','up to now it has used local materials','it will use local materials only next year','it has never used any local materials','hitherto 表示迄今为止。'),Q('hitherto',2,2,'A hitherto unknown fact was?','unknown before a particular point in time','already famous for centuries','certain to remain unknown forever','hitherto 可表示此前尚未发生或知晓。'),Q('hitherto',3,1,'Which sentence uses hitherto naturally?','The hitherto quiet station became busy after the new line opened.','Hitherto tomorrow, the station will be closed.','The station hitherto a train yesterday.','hitherto 修饰此前一直安静的车站。'),Q('hitherto',4,1,'Hitherto is closest to?','until then or until now','from now on','at exactly this place','其义为到那时或迄今。')]);
P('hitter','Hitter 由 hit 加施事后缀 -er 构成，指击球的人，尤常用于棒球中负责击球的球员。',C('hitter.s1','棒球比赛','The left-handed hitter waited for a fast pitch, then drove the ball deep into right field.','这名左打击球手等到一记快速球后，将球猛击到右外野深处。','The left-handed hitter waited for a fast pitch / then drove the ball / deep into right field.','hitter 指击球员；then 引出击球动作。','等待投球并将球击出体现棒球击球手身份。'),M('The hitter scored a run by refusing to swing at every pitch and leaving the bat in the dugout.','The hitter drove the pitch into the outfield and scored a run.','完全不挥棒且没有球棒不能完成击球得分。'),[Q('hitter',1,1,'In baseball, a hitter is a player who?','tries to strike the pitched ball','calls the weather for the stadium','repairs the pitcher’s mound','hitter 指击球员。'),Q('hitter',2,1,'A powerful hitter is known for?','sending the ball far when making contact','never holding a bat','catching every ball behind home plate','强打者能把球击得很远。'),Q('hitter',3,1,'Which person is the hitter in a baseball play?','the batter facing the pitcher','the umpire calling balls and strikes','the groundskeeper painting the lines','面对投手击球的人是 hitter。'),Q('hitter',4,1,'The suffix -er in hitter marks?','a person who hits','a place for storing bats','the past tense of hit','-er 表示执行击打动作的人。')]);
P('hive','Hive 源自古英语 hyf，名词指蜂箱或蜂群，也可比喻繁忙场所；作动词可指蜂群入箱或人群聚居。',C('hive.s3','繁忙场景','By noon, the quiet studio had become a hive of activity as designers assembled models and tested lights.','到了中午，安静的工作室变成了繁忙的场所，设计师们忙着组装模型并测试灯光。','By noon / the quiet studio had become a hive of activity / as designers assembled models and tested lights.','a hive of activity 是比喻搭配，形容忙碌热闹的地方。','多人同时工作使工作室充满活动，符合比喻义。'),M('The studio was a hive of activity because every worker sat alone and no task was underway.','The studio was a hive of activity as teams built and tested their designs.','无人工作且没有活动不符合“繁忙场所”。'),[Q('hive',1,1,'A beehive is a?','container where bees are kept','tool for cutting hay','place where a court hears a case','hive 名词可指蜂箱。'),Q('hive',2,2,'A hive of bees is a?','colony of bees living together','single bee flying alone','pile of dry grass','hive 也可指一群蜜蜂。'),Q('hive',3,3,'A hive of activity describes a place that is?','full of busy people and movement','completely empty and silent','dangerous because it is underwater','比喻义指忙碌热闹的场所。'),Q('hive',4,4,'If people hive together, they?','live closely together like a group','scatter in different countries','stop working permanently','hive 作动词可指群居。')]);
P('hoard','Hoard 源自古英语 hord“藏起来的财物”，可作动词指囤积、秘藏，也可作名词指隐藏储藏的一批钱财或物品。',C('hoard.s1','资源储备','The family hoarded clean water in sealed containers before the hurricane reached the island.','飓风抵达岛屿前，这家人把干净的水囤在密封容器里。','The family hoarded clean water / in sealed containers / before the hurricane reached the island.','hoard 作动词表示大量收集并保存，常含藏起来或超过所需之意。','预先储存大量饮用水以备灾害，体现囤积义。'),M('She hoarded food by giving away all her supplies and keeping none for herself.','She hoarded food by storing more supplies than she needed.','把所有物资送人并不构成囤积。'),[Q('hoard',1,1,'To hoard supplies is to?','collect and keep them, often in large amounts','use them all immediately','sell them before buying any','hoard 作动词指囤积、秘藏。'),Q('hoard',2,2,'A hidden hoard of coins is?','a stored collection of coins','a receipt for one coin','a machine that counts tickets','hoard 名词可指隐藏的储藏物。'),Q('hoard',3,1,'Why might people hoard food before a storm?','they fear supplies will become unavailable','they want every shop to remain full','they have already eaten all the food','担心短缺会促使人储存物资。'),Q('hoard',4,2,'Which sentence uses hoard as a noun?','Archaeologists uncovered a hoard of silver beneath the floor.','The family hoarded blankets before winter.','They will hoard enough rice tomorrow.','a hoard of silver 中 hoard 是名词。')]);
P('hoarse','Hoarse 源自古英语 hās，形容嗓音粗哑无力，可因感冒、长时间说话或大声呐喊而出现。',C('hoarse.s2','体育助威','After shouting through the entire final, the supporters were hoarse and could barely sing the team anthem.','整场决赛都在呐喊后，支持者们嗓子都喊哑了，几乎唱不出队歌。','After shouting through the entire final / the supporters were hoarse / and could barely sing the team anthem.','hoarse 作表语形容词，描述嗓音因喊叫而沙哑。','持续助威导致声音粗哑，符合 s2。'),M('After cheering all night, her voice was hoarse, clear, and stronger than before.','After cheering all night, her voice was hoarse, rough, and weak.','清亮有力与 hoarse 的粗哑无力相反。'),[Q('hoarse',1,1,'A hoarse voice sounds?','rough and weak','smooth and perfectly clear','silent because no one is speaking','hoarse 指声音嘶哑。'),Q('hoarse',2,2,'Someone may become hoarse after?','shouting for hours at a match','sleeping quietly in a silent room','drinking a glass of water','长时间喊叫可能使声音沙哑。'),Q('hoarse',3,1,'A cold can make a speaker sound?','hoarse','hollow only in appearance','homely in style','感冒可能导致嗓音嘶哑。'),Q('hoarse',4,2,'Which sentence uses hoarse correctly?','Her hoarse voice cracked after the long speech.','Her hoarse eyes blinked at the light.','The hoarse desk held several books.','hoarse 通常形容嗓音。')]);
P('hoax','Hoax 的来源尚不确定，可能与 hocus-pocus 一类戏法用语有关；作名词指骗局、恶作剧或蓄意散布的假消息，也可作动词表示欺骗。',C('hoax.s3','网络信息核验','The viral post claiming that the city had banned rain was a hoax, created to mislead readers and collect clicks.','那条声称市政府禁止下雨的爆红帖子是个骗局，目的是误导读者并骗取点击量。','The viral post claiming that the city had banned rain / was a hoax / created to mislead readers and collect clicks.','hoax 作名词可指蓄意散布的假消息；created 分词补充其目的。','明显不可能的消息被故意传播以误导公众，符合假消息义。'),M('The public notice was a hoax even though it was issued by the city and accurately described the new rule.','The viral anonymous post was a hoax because the city had issued no such rule.','经市政府正式发布且内容属实的公告不是骗局。'),[Q('hoax',1,1,'To hoax someone is to?','trick them into believing something false','give them verified information','help them find a lost document','hoax 作动词指欺骗。'),Q('hoax',2,2,'A practical hoax is?','a trick or deception played on people','a signed legal agreement','a weather report confirmed by instruments','hoax 名词可指骗局或恶作剧。'),Q('hoax',3,3,'A deliberate false report spread online is a?','hoax','hobby','hitch','蓄意误导公众的假消息可称 hoax。'),Q('hoax',4,1,'Why should a shocking post be checked before sharing?','it may be a hoax designed to fool readers','every viral claim is automatically true','checking sources always makes it more popular','核实来源可避免传播骗局。')]);
P('hobble','Hobble 的更早来源并不确定；作动词表示跛行或使行动受限，常因腿部受伤或被绊住。',C('hobble.s1','受伤与行动','The injured runner hobbled toward the medical tent, leaning on a teammate for support.','受伤的跑者一瘸一拐地走向医疗帐篷，靠队友搀扶着。','The injured runner hobbled toward the medical tent / leaning on a teammate / for support.','hobble 描写因伤而艰难跛行；toward 指移动方向。','需要队友搀扶说明步态困难。'),M('The sprinter hobbled smoothly on both legs without any pain or difficulty.','The sprinter hobbled slowly on one injured leg.','双腿无痛且步态顺畅与跛行相反。'),[Q('hobble',1,1,'To hobble is to walk?','with difficulty, often because of an injury','at a steady effortless run','without moving either foot','hobble 指艰难地跛行。'),Q('hobble',2,1,'A person with a painful ankle may?','hobble across the room','sprint without discomfort','fly to the hospital','脚踝疼痛可能导致跛行。'),Q('hobble',3,1,'Which detail suggests hobbling?','one leg bears less weight and each step is uneven','both feet move smoothly at the same pace','the person remains seated throughout','步态不均且避开一条腿说明跛行。'),Q('hobble',4,1,'The verb hobble can also mean to?','restrict someone’s movement','make someone’s hearing sharper','turn a field into a haystack','比喻义可表示限制行动。')]);
P('hobby','Hobby 源自 hobbyhorse（玩具木马或业余消遣）一类旧表达，现代指闲暇时为乐趣而做的活动或持续追求的兴趣。',C('hobby.s1','休闲活动','Repairing old radios began as a hobby, but Sam eventually learned enough to restore several for the community center.','修理旧收音机起初只是萨姆的业余爱好，但他后来学会了修复几台送给社区中心。','Repairing old radios began as a hobby / but Sam eventually learned enough / to restore several for the community center.','hobby 是可数名词；动名词 Repairing 作主语。','他在空闲时间因兴趣修理收音机，体现业余爱好。'),M('Her hobby was mandatory overtime that she disliked and never chose in her free time.','Her hobby was building model boats for pleasure in her spare time.','被迫且不喜欢的加班不是业余爱好。'),[Q('hobby',1,1,'A hobby is an activity done mainly?','for pleasure in one’s free time','because a court ordered it','to earn every person’s salary','hobby 指闲暇时为乐趣从事的活动。'),Q('hobby',2,2,'A person’s hobby in astronomy means they?','pursue astronomy as a personal interest','work as a professional astronaut necessarily','avoid looking at the night sky','hobby 也可指某一领域的兴趣。'),Q('hobby',3,1,'Which is most clearly a hobby?','painting landscapes on weekends for enjoyment','filing a required tax return','attending a compulsory safety briefing','周末为乐趣作画是爱好。'),Q('hobby',4,2,'A hobby need not be someone’s?','paid full-time job','personal interest','leisure activity','爱好不一定是有偿全职工作。')]);
P('hockey','Hockey 源自法语 hoquet“牧羊杖、弯头棍”，现指用球杆进行的曲棍球或冰上以冰球进行的冰球运动。',C('hockey.s2','冰上运动','The hockey players changed lines quickly as the puck slid toward the boards during the second period.','第二节比赛中，冰球滑向挡板时，球员们迅速换了阵容线。','The hockey players changed lines quickly / as the puck slid toward the boards / during the second period.','冰球义常用 puck 指冰球；change lines 是冰球换人术语。','冰球、挡板和换线场景明确对应冰球。'),M('The hockey team skated on a grass field and tried to strike a round ball with curved sticks.','The field-hockey team played on grass and used curved sticks to move the ball.','草地上击球的比赛是草地曲棍球，不是冰球。'),[Q('hockey',1,1,'Field hockey is played with?','curved sticks and a ball on a field','skates and a puck on ice','rackets and a net indoors','草地曲棍球使用球杆和球。'),Q('hockey',2,2,'Ice hockey is played on?','ice, with skates and a puck','a grass field, with a round ball','a tennis court, with rackets','冰球在冰面进行并使用 puck。'),Q('hockey',3,1,'What distinguishes the puck in ice hockey?','it is a hard disk slid across the ice','it is a feathered ball kicked on grass','it is a net attached to a stick','冰球 puck 是在冰上滑动的硬圆盘。'),Q('hockey',4,1,'Which sentence clearly describes field hockey?','The players ran on grass while passing a ball with sticks.','The players skated and shot a puck into the goal.','The players served a ball over a tennis net.','在草地上跑动并击球对应草地曲棍球。')]);
P('hoe','Hoe 源自古英语中表示农用锄具的词，指短柄除草松土工具，也可作动词表示用锄头耕作。',C('hoe.s1','园艺与除草','Mina used a hoe to loosen the soil around the tomatoes without cutting their shallow roots.','米娜用锄头松开西红柿周围的土壤，同时避免切断浅层根系。','Mina used a hoe to loosen the soil / around the tomatoes / without cutting their shallow roots.','hoe 作名词指园艺工具；to loosen 说明其用途。','松土和除草是锄头的用途。'),M('He hoed the garden by using a violin bow to cut weeds beneath the soil.','He hoed the garden with a short-handled tool for loosening soil.','小提琴弓不是用于锄地的工具。'),[Q('hoe',1,1,'A hoe is a garden tool used to?','loosen soil and remove weeds','cut tall hay with a curved blade','lift heavy crates with a rope','hoe 指锄头。'),Q('hoe',2,1,'To hoe a vegetable bed means to?','work the soil with a hoe','cover the bed with a blanket','water it with a sprinkler only','hoe 作动词表示用锄头耕作。'),Q('hoe',3,1,'Which tool would help clear weeds between rows?','a hoe','a harpsichord','a hockey puck','锄头适合处理行间杂草。'),Q('hoe',4,1,'A gardener should hoe carefully near tomatoes to avoid?','damaging their shallow roots','making the plants bloom immediately','turning the soil into water','浅根作物附近需小心用锄。')]);
P('hog','Hog 源自古英语 hogg 一类表示猪的词；它也可作动词，口语中指独占资源或不让别人分享。',C('hog.s1','农场动物','The farmer separated the young hogs from the feed trough so each animal could eat safely.','农场主把小猪分开到饲料槽旁，让每只动物都能安全进食。','The farmer separated the young hogs from the feed trough / so each animal / could eat safely.','hog 作名词指猪；young hogs 是小猪。','饲槽边的动物是农场饲养的猪。'),M('The farmer called the flock of sheep hogs and prepared pork feed for them.','The farmer called the pigs hogs and brought them their feed.','羊不是 hog；应将此词用于猪。'),[Q('hog',1,1,'A hog is a?','pig, especially a large one','young chicken raised for eggs','bird of prey with sharp talons','hog 指猪。'),Q('hog',2,1,'If one guest hogs the microphone, the guest?','keeps it and prevents others from using it','passes it around fairly','turns it into a farm animal','动词 hog 表示独占资源。'),Q('hog',3,1,'Which scene shows hogging?','one person uses all the shared table space','everyone takes turns using the bench','a farmer feeds pigs at the barn','独占全部共享空间是 hog。'),Q('hog',4,1,'“Don’t hog the conversation” asks someone not to?','dominate all the speaking time','speak clearly when asked','leave the room immediately','不要 hog 谈话即不要独占发言。')]);
P('hoist','Hoist 可能经荷兰语 hijsen“升起”进入英语，作动词指用绳索或设备吊升、吊装，也可作名词指起重装置。',C('hoist.s2','装卸与物流','A crane hoisted the steel container from the truck and lowered it carefully onto the ship’s deck.','起重机把钢制集装箱从卡车上吊起，再小心放到船甲板上。','A crane hoisted the steel container from the truck / and lowered it carefully / onto the ship’s deck.','hoist 作动词表示用起重设备吊装货物。','起重机完成吊起和移运，符合 s2。'),M('The crew hoisted the container by pushing it along the ground without lifting it.','The crane hoisted the container clear of the ground before moving it.','沿地面推而未吊起不符合 hoist 的吊装义。'),[Q('hoist',1,1,'To hoist a heavy flag is to?','raise it, often with ropes or a device','lower it beneath the ground','fold it into a small square','hoist 表示举起或升起。'),Q('hoist',2,2,'A crane hoists cargo when it?','lifts and moves the goods','paints the cargo’s label','checks the goods’ owner','起重机吊起并搬运货物。'),Q('hoist',3,3,'A ship’s hoist is a device for?','lifting heavy objects','steering the ship through fog','measuring the crew’s height','hoist 名词指起重装置。'),Q('hoist',4,1,'Which action is a hoist?','raising a piano to an upper floor with a lifting rig','rolling a piano down a flat hallway','tuning a piano before a concert','用吊具提升钢琴属于 hoist。')]);
P('hold','Hold 源自古英语 healdan，可指手握或抱住、容纳、举行活动、保持状态、担任职位；名词也可指握力或控制力。',[C('hold.s3','会议安排','The board will hold its annual meeting in the library because the larger hall is being repaired.','董事会将在图书馆举行年度会议，因为较大的礼堂正在维修。','The board will hold its annual meeting in the library / because the larger hall / is being repaired.','hold 作动词可表示举行会议；its annual meeting 是宾语。','会议安排在图书馆举行，体现 event 义。'),C('hold.s2','容纳能力','This thermos holds enough soup for four workers, though it fits easily inside a small backpack.','这个保温壶能装下供四名工人喝的汤，尽管它很容易放进小背包。','This thermos holds enough soup for four workers / though it fits easily / inside a small backpack.','hold 可表示容纳一定数量；enough soup for 指容量。','保温壶容量与可装份量说明容纳义。')],M('The hall can hold 300 guests, so it holds only 12 people comfortably.','The hall can hold 300 guests, so it can accommodate a large crowd.','300人的容量与只容纳12人互相矛盾。'),[Q('hold',1,1,'Please hold this parcel for a moment means?','keep it in your hands temporarily','put it in an oven to bake','give it to a stranger immediately','hold 的基本动作义是拿着。'),Q('hold',2,2,'A tank that holds 500 liters can?','contain that amount of liquid','raise its contents into the air','conduct a meeting about water','hold 可指容纳。'),Q('hold',3,3,'The school will hold an election means it will?','organize and carry out the election','cancel every vote before it begins','keep the ballot box in a hand','hold 可表示举行活动。'),Q('hold',4,5,'She holds the title of treasurer means she?','has that position or office','is physically holding a title page','has lost the election','hold 可指担任职务或拥有头衔。')]);
P('hold back','Hold back 是 hold 与 back 构成的短语动词，可指忍住情绪或行动，也可指扣留、保留信息或阻止进展。',C('hold back.s1','情绪控制','Although she was angry about the unfair decision, Noor held back her criticism until the meeting ended.','尽管诺尔对不公决定很生气，她还是忍到会议结束后才提出批评。','Although she was angry about the unfair decision / Noor held back her criticism / until the meeting ended.','hold back 在此表示克制、忍住；until 标出延后的时间。','她没有立即表达批评，体现克制情绪或言语。'),M('He held back his tears by crying loudly throughout the ceremony.','He held back his tears and waited until he was alone.','当众大声哭与忍住眼泪相反。'),[Q('hold back',1,1,'To hold back tears is to?','try not to cry','make oneself cry harder','lend someone a box of tissues','hold back 可指忍住情绪。'),Q('hold back',2,1,'A company may hold back information by?','keeping it from being shared','publishing it immediately','translating it into every language','短语也可指扣留信息。'),Q('hold back',3,1,'If fear holds a climber back, it?','prevents the climber from progressing','helps the climber reach the summit faster','gives the climber a map','hold back 可表示阻碍进展。'),Q('hold back',4,1,'Which sentence uses hold back for restraint?','She held back a sharp reply.','She held a book in both hands.','She backed a truck into the garage.','忍住尖锐回应符合 hold back。')]);
P('hold on','Hold on 是短语动词，可表示稍等片刻，也可表示紧紧抓住或在困难中坚持。',C('hold on.s1','电话沟通','“Hold on while I check the booking,” the clerk said before placing the caller on a brief pause.','职员在让来电者稍等时说：“请等一下，我查一下预订。”','“Hold on while I check the booking” / the clerk said / before placing the caller on a brief pause.','电话用语 hold on 表示请稍等；while 从句说明等待期间要做的事。','职员暂停通话查询，体现“等一下”。'),M('The operator said “hold on” and then immediately hung up without waiting or checking anything.','The operator said “hold on” and asked the caller to wait while she checked the file.','hold on 要求暂等；立刻挂断没有让对方等候。'),[Q('hold on',1,1,'On a phone, “Hold on a moment” means?','please wait briefly','please send the phone away','please end the call forever','电话里 hold on 表示稍等。'),Q('hold on',2,1,'A climber told to hold on should?','keep a firm grip','release the rope at once','walk away from the cliff','hold on 可表示紧紧抓住。'),Q('hold on',3,1,'If a team holds on through a difficult season, it?','keeps going despite trouble','quits before the first game','forgets the season happened','hold on 也可指坚持。'),Q('hold on',4,1,'Which response fits “Hold on, I’ll check”?','wait a short time while I look it up','leave immediately without listening','write down a different phone number','句子要求对方等片刻。')]);
P('hold-up','Hold-up 由 hold 与 up 组成，作名词可指持械抢劫，也可指造成进度变慢的耽搁或阻碍。',C('hold-up.s1','交通与延误','A broken signal caused a hold-up on the rail line, and the afternoon trains arrived nearly an hour late.','信号故障导致铁路线上出现延误，下午的列车晚到近一小时。','A broken signal caused a hold-up on the rail line / and the afternoon trains arrived / nearly an hour late.','hold-up 作名词表示延误；caused a hold-up 描述故障造成的后果。','列车被耽搁并晚点，符合 delay 义。'),M('The train service reported no hold-up even though every train was delayed for an hour.','The train service reported a hold-up because every train was delayed for an hour.','全线延误与“没有耽搁”相矛盾。'),[Q('hold-up',1,1,'A hold-up on a road is usually?','a delay that slows traffic','a fast lane with no cars','a ticket for a concert','hold-up 可指耽搁。'),Q('hold-up',2,1,'A bank hold-up is a?','robbery at a bank','routine account statement','plan to save money','该词也可指抢劫。'),Q('hold-up',3,1,'Which event caused a hold-up?','a fallen tree blocking the only road','a clear road with steady traffic','a bus arriving exactly on time','道路受阻造成延误。'),Q('hold-up',4,1,'The construction hold-up means the work?','was delayed by a problem','finished months ahead of plan','was never started or discussed','施工 hold-up 指进度延误。')]);
P('holder','Holder 由 hold 加施事或器具后缀 -er 构成，既可指持有某物的人，也可指用于固定或存放物品的容器。',C('holder.s1','厨房用品','The ceramic spoon holder sits beside the stove, keeping wet utensils off the clean counter.','陶瓷勺架放在炉子旁，让湿餐具不碰干净的台面。','The ceramic spoon holder sits beside the stove / keeping wet utensils / off the clean counter.','holder 作名词表示容器或支架；keeping 补充它的用途。','勺架用来放置餐具，体现容器义。'),M('The ticket holder was a person who had never received or possessed a ticket.','The ticket holder was the passenger whose name appeared on the ticket.','holder 指拥有或持有该票的人。'),[Q('holder',1,1,'A ticket holder is someone who?','possesses or is named on the ticket','prints every ticket at a station','checks the weather before boarding','holder 可指持票人。'),Q('holder',2,1,'A toothbrush holder is an object that?','keeps toothbrushes in place','holds a person’s job title','cleans the bathroom floor automatically','holder 也可指支架或容器。'),Q('holder',3,1,'A passport holder must show?','the passport they possess','a flowerpot without a passport','someone else’s train timetable','passport holder 指持有护照者。'),Q('holder',4,1,'Which is a holder in the container sense?','a wall-mounted cup for pens','a person listed as the account owner','a passenger carrying a paper ticket','装笔的杯架是器具义。')]);
P('holdings','Holdings 是 holding 的复数形式，常指个人或机构拥有的股份、资产或土地。',C('holdings.s1','投资与资产','The foundation reviewed its holdings in renewable-energy companies before publishing the annual investment report.','基金会在发布年度投资报告前，审查了其持有的可再生能源公司股份。','The foundation reviewed its holdings in renewable-energy companies / before publishing / the annual investment report.','holdings 作复数名词，指拥有的股份或资产；in 引出投资对象。','审查公司股份并写投资报告对应金融资产义。'),M('The fund sold all its holdings but continued to describe the shares it still owned as a large portfolio.','The fund sold part of its holdings and listed the remaining shares in its portfolio.','若股份已全部出售，就不再拥有这些 holdings。'),[Q('holdings',1,1,'A company’s holdings in another firm are?','shares or assets it owns there','the number of meetings it holds','the tools stored in a workshop','holdings 常指持有的股份或资产。'),Q('holdings',2,1,'A report on land holdings lists?','property or land owned by a person or group','all the roads someone has driven on','future plans that have not been made','holdings 也可指持有的土地。'),Q('holdings',3,1,'If an investor reduces their holdings, they?','own fewer shares or assets','increase every investment automatically','stop reading financial reports','减少 holdings 即减持资产。'),Q('holdings',4,1,'Which phrase is natural?','the fund’s holdings in several companies','the fund’s holdings of yesterday’s weather','the fund holdsings every meeting','holdings 可与 in 表示持有的公司股份。')]);
P('holdover','Holdover 由 hold over 组合构成，指从以前时期保留下来、延续到现在的事物或安排。',C('holdover.s1','制度延续','The interim director is a holdover from the previous administration and will stay until the new board appoints a replacement.','这位临时主管是前一届管理层留下的人选，会留任到新董事会任命继任者为止。','The interim director is a holdover from the previous administration / and will stay / until the new board appoints a replacement.','holdover 指前一时期留下并继续存在的人或事。','主管来自上一届并暂时延续任职，符合“遗留物”义。'),M('The new policy was a holdover from the future because it had already existed for decades.','The new policy was a holdover from the previous administration because it had existed for decades.','holdover 指从过去延续而来，不是来自未来。'),[Q('holdover',1,1,'A holdover from an earlier period is something?','kept or continued from before','invented only for the future','removed before it can begin','holdover 指以前留下来的东西。'),Q('holdover',2,1,'A holdover employee remains from?','the previous management or period','a company that has not yet opened','a completely unrelated organization','人可以作为前一时期的遗留成员。'),Q('holdover',3,1,'Which could be called a holdover?','an old rule still used by the new board','a rule drafted today and never adopted','a plan scheduled only for next year','从旧制度延续的规定是 holdover。'),Q('holdover',4,1,'The word holdover emphasizes that something?','persists after the period it came from','was created after it disappeared','cannot be retained at all','它突出从先前时期延续下来。')]);
P('hole','Hole 源自古英语 hol，名词可指孔洞、地坑、缺陷或高尔夫球洞；作动词可表示打孔或把球击入洞中。', [C('hole.s1','修理与结构','A tiny hole in the roof let rainwater drip onto the library’s oldest map.','屋顶上的一个小孔让雨水滴到了图书馆最古老的地图上。','A tiny hole in the roof / let rainwater drip / onto the library’s oldest map.','hole 表示穿透表面的孔洞；let 后接动词原形 drip。','雨水穿过屋顶孔洞滴入室内，体现 s1。'),C('hole.s5','高尔夫运动','On the final green, the golfer holed the ball with a gentle putt and won the tournament.','在最后一处果岭上，球手轻轻推杆将球击入洞中，赢得了比赛。','On the final green / the golfer holed the ball / with a gentle putt / and won the tournament.','hole 作动词可表示把球击入球洞。','球被推入果岭球洞，体现动词义。')],M('The golf ball holed the cup by stopping several feet away from the opening.','The golf ball went into the cup, so the golfer holed it on the final putt.','停在洞口几英尺外并没有打进球洞。'),[Q('hole',1,1,'A hole through a wall is?','an opening from one side to the other','a painted line on its surface','a solid piece of new brick','hole 可指穿透物体的孔。'),Q('hole',2,2,'A rabbit’s hole in the ground is a?','hollow place or burrow','metal hook on a fence','roof above a house','坑穴或洞穴是 hole 的一义。'),Q('hole',3,3,'A hole in an argument is a?','weakness or missing point in the reasoning','round opening in a golf green','tool used to tighten a screw','比喻义指论证漏洞。'),Q('hole',4,4,'In golf, to hole the ball is to?','hit it into the cup','carry it back to the tee by hand','throw it outside the course','动词 hole 表示将球击入洞。')]);
P('holiday','Holiday 源自古英语 hāligdæg“圣日”，名词可指节日、休假日或一段假期；在英式英语中也可作动词表示度假。',C('holiday.s3','旅行与休假','They holidayed on the coast each August, renting the same cottage near the dunes.','他们每年八月都到海岸度假，租住沙丘附近的同一间小屋。','They holidayed on the coast each August / renting the same cottage / near the dunes.','holiday 作动词表示度假；on the coast 指度假地点。','每年去海岸休假符合动词义。'),M('They holidayed by working every night and refusing to take any time away from work.','They holidayed by spending a week resting on the coast.','持续夜间工作并未休假。'),[Q('holiday',1,1,'A public holiday is a day when?','many people do not work','everyone must attend school','all shops are required to open','holiday 可指节假日。'),Q('holiday',2,2,'A two-week holiday from school is?','a period of rest or vacation','one hour of homework','a school examination','holiday 也可指一段假期。'),Q('holiday',3,3,'In British usage, to holiday somewhere means to?','spend a vacation there','close the place permanently','decorate it for a festival','holiday 可作动词“度假”。'),Q('holiday',4,1,'Which phrase uses holiday as a noun?','the winter holiday begins on Monday','they holiday near the sea','she holidayed with her family','冬假中的 holiday 是名词。')]);
P('holism','Holism 由希腊语 holos“整体”与 -ism 构成，指研究或理解系统时把整体看作多于各部分简单相加的观点。',C('holism.s1','系统思维','Holism led the ecologists to study the forest, its soil, and its animal populations as one connected system.','整体论促使生态学家把森林、土壤和动物种群作为一个相互联系的系统来研究。','Holism led the ecologists / to study the forest, its soil, and its animal populations / as one connected system.','holism 是抽象名词，体现整体理解方法；as 引出整体视角。','同时考察各部分关系而非孤立研究，符合整体论。'),M('The researcher practiced holism by studying one leaf alone and ignoring every other part of the forest.','The researcher practiced holism by examining how the leaf, soil, and insects interacted.','只孤立研究一片叶子忽略整体关系。'),[Q('holism',1,1,'Holism encourages people to study?','a system as a connected whole','each part while ignoring every relationship','only the smallest object available','holism 强调整体性。'),Q('holism',2,1,'A holistic view of a forest considers?','how plants, animals, and soil interact','one tree with no surrounding ecosystem','only the price of timber','整体论会考察各部分相互作用。'),Q('holism',3,1,'Holism is the opposite of an approach that?','reduces everything to isolated parts','connects related factors','looks at the whole system','整体论反对只看孤立部分。'),Q('holism',4,1,'The suffix -ism often forms a noun for?','a doctrine, approach, or system of thought','a person who performs a single task','the past tense of an action','holism 是一种思想方法。')]);
P('holistic','Holistic 由 holism 加 -ic 构成，表示从整体角度处理问题；医学语境中尤其强调兼顾身心而非只看单一疾病。',C('holistic.s2','医疗与照护','The clinic offered holistic care that considered the patient’s pain, sleep, stress, and family support.','诊所提供整体照护，兼顾病人的疼痛、睡眠、压力和家庭支持。','The clinic offered holistic care / that considered the patient’s pain, sleep, stress, and family support.','holistic 修饰 care；that 从句列出整体照护考虑的因素。','同时考虑身体和心理等多方面情况，体现医学义。'),M('The clinic called its treatment holistic even though it considered only one symptom and ignored the patient’s well-being.','The clinic used a holistic plan that considered symptoms, stress, sleep, and support.','只关注单一症状而忽略整体状态，不符合 holistic。'),[Q('holistic',1,1,'A holistic approach considers?','the whole situation and how its parts relate','one isolated detail only','only the cheapest available option','holistic 表示从整体出发。'),Q('holistic',2,2,'Holistic medical care may address?','body, mind, and the patient’s wider circumstances','only a laboratory number','only the clinic’s building design','医学中强调身心及生活环境。'),Q('holistic',3,1,'Which plan is holistic?','one that considers sleep, stress, symptoms, and support','one that ignores every factor except a single symptom','one that treats unrelated patients identically','综合多方面因素的计划是 holistic。'),Q('holistic',4,1,'Holistic is related to the idea of?','a whole rather than separate pieces','a hole in the ground','a holiday from work','词义根源是整体。')]);
P('holistically','Holistically 由 holistic 加副词后缀 -ally 构成，表示从整体角度、结合相关因素地进行思考或处理。',C('holistically.s1','综合评估','The adviser assessed the family holistically, considering income, care duties, housing, and the children’s schooling together.','顾问综合评估了这个家庭，把收入、照护责任、住房和孩子的学业一并考虑。','The adviser assessed the family holistically / considering income, care duties, housing, and the children’s schooling together.','holistically 修饰 assessed，说明评估方式；considering 列举综合因素。','同时考察多种相关状况体现整体评估。'),M('The adviser assessed the family holistically by considering income alone and ignoring housing and care needs.','The adviser assessed the family holistically by reviewing income, housing, care, and schooling.','只看收入而忽略其他状况不是整体评估。'),[Q('holistically',1,1,'To assess a case holistically is to?','consider all important related factors together','look at a single number in isolation','avoid gathering any information','holistically 表示整体地、全面地。'),Q('holistically',2,1,'Which review is done holistically?','one that weighs health, housing, and family support','one that checks only a person’s shoe size','one that skips all relevant circumstances','整体评估会纳入多种相关因素。'),Q('holistically',3,1,'Holistically is an adverb that modifies?','how an action is carried out','the number of people in a room','the spelling of a noun only','副词说明动作采取何种方式。'),Q('holistically',4,1,'The core idea behind holistically is?','viewing the whole system','cutting an object into holes','taking a day off','其核心是从整体角度看。')]);
P('holler','Holler 是口语词，来源不完全确定；作动词表示大声喊叫，作名词表示远处可听见的一声叫喊。',C('holler.s2','声音与回应','A loud holler from the back of the hall alerted the stage crew that a cable had come loose.','大厅后方传来一声大喊，提醒舞台工作人员有根电缆松脱了。','A loud holler from the back of the hall / alerted the stage crew / that a cable had come loose.','holler 作名词表示大声叫喊声；that 从句说明喊声传递的消息。','大声喊声使远处工作人员听见，符合名词义。'),M('She hollered by whispering so softly that nobody in the next room could hear her.','She hollered across the hall so the crew could hear her warning.','无人能听见的低声耳语不属于大声喊叫。'),[Q('holler',1,1,'To holler across a field is to?','shout loudly so someone far away can hear','write a note in a quiet room','sing softly into a microphone','holler 作动词表示大声喊。'),Q('holler',2,2,'A holler from outside is?','a loud cry or shout','a written invitation','a type of farm tool','holler 作名词指喊叫声。'),Q('holler',3,1,'Why might a worker holler in a noisy factory?','to make a warning audible at a distance','to reduce the volume of every machine','to keep the warning secret','大声喊可让远处的人听见警告。'),Q('holler',4,1,'Which is closest to holler?','yell','murmur','calculate','holler 最接近 yell。')]);
P('hollow','Hollow 源自古英语 holh，形容内部中空、表面凹陷、声音空洞或言辞虚伪；作动词可表示挖空。',[C('hollow.s4','承诺与真诚','The apology sounded hollow because the manager repeated it but made no effort to correct the mistake.','经理一再道歉却不纠正错误，所以这番道歉听起来很空洞。','The apology sounded hollow / because the manager repeated it / but made no effort to correct the mistake.','hollow 作表语形容词可表示缺乏真诚或实际内容。','言辞重复却没有行动，体现虚伪空洞义。'),C('hollow.s5','木工与制作','The craftsperson hollowed out the log to make a lightweight canoe.','工匠把原木挖空，做成一艘轻便的独木舟。','The craftsperson hollowed out the log / to make / a lightweight canoe.','hollow 作动词常与 out 连用，表示挖空内部。','从原木中移除木料制成船体，体现动词义。')],M('His hollow apology was sincere because he admitted the harm and repaired what he had broken.','His hollow apology sounded insincere because he refused to repair the damage.','承认伤害并积极补救体现真诚，不是 hollow 的虚伪义。'),[Q('hollow',1,1,'A hollow pipe is?','empty inside','solid all the way through','curved inward on its outer surface only','hollow 可指内部中空。'),Q('hollow',2,2,'Hollow cheeks look?','sunken or curved inward','round and full','covered with feathers','hollow 可形容面颊凹陷。'),Q('hollow',3,3,'A hollow sound is often?','echoing and lacking a full resonance','clear and richly resonant','completely inaudible','hollow 可形容空洞沉闷的声音。'),Q('hollow',4,4,'A hollow promise is one that?','lacks sincerity or real value','has been carefully fulfilled','is made of wood with a hole','比喻义指空洞、不真诚。')]);
P('holocaust','Holocaust 源自希腊语 holokauston“完全烧尽的祭品”；小写可指大规模屠杀或浩劫，大写 The Holocaust 专指纳粹对欧洲犹太人的大屠杀。',C('holocaust.s2','历史教育','The museum’s Holocaust exhibition documents the Nazi persecution and murder of millions of Jews during World War II.','博物馆的纳粹大屠杀展览记录了第二次世界大战期间纳粹对数百万犹太人的迫害与屠杀。','The museum’s Holocaust exhibition / documents the Nazi persecution and murder / of millions of Jews / during World War II.','专名 Holocaust 大写，特指纳粹大屠杀；exhibition documents 表示展览记载史实。','时间、施害者和受害群体与历史专指义相符。'),M('The museum described the Holocaust as a minor disagreement that caused no deaths.','The museum documented the Holocaust as the Nazi genocide of millions of Jews during World War II.','把大规模屠杀说成没有死亡的小争执，严重歪曲历史事实。'),[Q('holocaust',1,1,'In lower-case general use, a holocaust can mean?','large-scale destruction or killing','a peaceful holiday celebration','a minor delay on a train line','小写可泛指浩劫或大规模屠杀。'),Q('holocaust',2,2,'The Holocaust with a capital H refers specifically to?','the Nazi genocide of Jews during World War II','any modern sports competition','a fire drill at a museum','大写专指纳粹对犹太人的大屠杀。'),Q('holocaust',3,2,'Why do museums preserve records of the Holocaust?','to document victims’ experiences and historical crimes','to turn the event into a fictional game','to claim that no one was persecuted','保存史料有助记录受害者经历和罪行。'),Q('holocaust',4,1,'Which wording treats this history accurately?','the Holocaust was a genocide carried out by Nazi Germany','the Holocaust was merely a harmless disagreement','the Holocaust involved no victims','准确表述应承认其种族灭绝性质。')]);
P('holy','Holy 源自古英语 hālig，形容与神或宗教相关、圣洁虔诚；口语感叹词组 holy cow 等还可用来加强惊讶语气。',C('holy.s3','口语感叹','“Holy cow, that was close!” shouted Ben when the cyclist narrowly avoided the open car door.','骑车人险些撞上敞开的车门时，本喊道：“天哪，好险！”','“Holy cow, that was close!” / shouted Ben / when the cyclist narrowly avoided the open car door.','holy cow 是口语感叹语，holy 加名词用于强调惊讶。','险些发生碰撞引发惊呼，体现语气加强义。'),M('She whispered “holy cow” as a formal prayer in the middle of a quiet religious service.','She shouted “holy cow” as a surprised reaction to the sudden crash.','holy cow 通常是口语感叹语，不是正式祷告。'),[Q('holy',1,1,'A holy site is connected with?','God or a religious tradition','a company’s stock portfolio','a sporting tournament only','holy 表示宗教上的神圣。'),Q('holy',2,2,'A holy person is often described as?','morally pure and devoted to God','careless and dishonest','skilled at driving a train','holy 可形容虔诚圣洁的人。'),Q('holy',3,3,'“Holy cow!” is most likely an expression of?','surprise or strong emphasis','a quiet scientific measurement','a formal job title','口语里可用来加强惊讶语气。'),Q('holy',4,1,'Which phrase uses holy in its religious sense?','a holy book used in worship','a holy long delay on a highway','a holy pile of office forms','宗教仪式中的圣书体现字面义。')]);
P('holy person','Holy person 是由 holy 与 person 组成的名词短语，指虔诚、品行高尚并受到宗教敬仰的人。',C('holy person.s1','宗教人物','Pilgrims visited the shrine to learn about the holy person whose acts of compassion had inspired the town.','朝圣者来到圣所，了解这位以慈悲行为感召全镇的圣人。','Pilgrims visited the shrine / to learn about the holy person / whose acts of compassion had inspired the town.','holy person 指受宗教敬仰的人；whose 引出其受敬仰的原因。','慈悲行为与朝圣敬仰体现圣人形象。'),M('The community called a cruel thief a holy person because he repeatedly harmed the poor.','The community honored the compassionate teacher as a holy person.','残害穷人的行为与圣洁虔诚的品格相反。'),[Q('holy person',1,1,'A holy person is someone regarded as?','deeply religious and morally good','a skilled professional athlete','a person who owns a holy building','holy person 指圣洁虔诚的人。'),Q('holy person',2,1,'Why might pilgrims visit a shrine for a holy person?','to honor or learn about that person','to register a home loan','to watch an ice-hockey match','朝圣者会敬仰宗教人物。'),Q('holy person',3,1,'Which behavior fits a holy person in a religious story?','showing compassion and devotion','deceiving people for money','refusing every act of kindness','慈悲和虔诚符合圣人形象。'),Q('holy person',4,1,'Holy person is a phrase naming?','a person considered saintly','a building where people worship','a religious holiday on a calendar','该短语指人而非地点或节日。')]);
P('holy place','Holy place 是由 holy 与 place 构成的名词短语，指宗教礼拜、祈祷或朝圣所用的圣地。',C('holy place.s1','礼拜与朝圣','Worshippers removed their shoes before entering the holy place, following the community’s long-standing custom.','礼拜者遵照社区沿袭已久的习俗，在进入圣地前脱下鞋子。','Worshippers removed their shoes / before entering the holy place / following the community’s long-standing custom.','holy place 指宗教礼拜或朝圣场所；before 引出进入之前的动作。','礼拜者遵守场所习俗，体现圣地语义。'),M('The guide called the noisy car park a holy place although no one worshipped or prayed there.','The guide called the quiet shrine a holy place where visitors came to pray.','无人礼拜或祈祷的停车场不符合圣地含义。'),[Q('holy place',1,1,'A holy place is a site used for?','worship or religious pilgrimage','storing company shares','repairing farm tools','holy place 指宗教圣地。'),Q('holy place',2,1,'A shrine may be called a holy place because people?','pray or show religious respect there','use it as a hockey rink','store hay inside it','祈祷和宗教敬意使其成为圣地。'),Q('holy place',3,1,'Which place is most likely holy?','a temple visited by worshippers','an empty parking meter','a factory loading dock','宗教场所可称 holy place。'),Q('holy place',4,1,'The adjective holy in holy place describes?','religious significance','the building’s height','its distance from a headland','holy 表示宗教神圣性。')]);
P('homage','Homage 经古法语 hommage 进入英语，指以言语、仪式或作品向某人表示深切敬意或致敬。',C('homage.s1','艺术致敬','The director’s new film pays homage to the silent-movie era through monochrome scenes and title cards.','导演的新电影通过黑白画面和字幕卡向无声电影时代致敬。','The director’s new film pays homage to the silent-movie era / through monochrome scenes / and title cards.','pay homage to 是固定搭配，表示向……致敬。','作品用早期电影的风格表达敬意。'),M('The speech paid homage to the volunteers by mocking their work and dismissing their service.','The speech paid homage to the volunteers by thanking them for their service.','嘲笑和贬低他人不构成致敬。'),[Q('homage',1,1,'To pay homage to a scientist is to?','show deep respect for the scientist','demand a refund from the scientist','hide the scientist’s work','homage 表示敬意、致敬。'),Q('homage',2,1,'Which could be an artistic homage?','a new song echoing the style of an admired composer','a review pretending the composer never existed','a list of unrelated grocery prices','作品借鉴敬仰者风格可表达致敬。'),Q('homage',3,1,'The phrase “pay homage to” means?','honor or show respect to','charge money from','argue loudly with','pay homage to 是致敬。'),Q('homage',4,1,'A memorial ceremony may serve as homage to?','people whose contributions are honored','a broken machine awaiting repair','a train delayed by a signal','纪念仪式可向受敬仰者致敬。')]);
P('home','Home 源自古英语 hām，名词可指居所、故乡或动植物栖息地，也可作形容词表示家庭、本国或主场的，作副词表示在家或回家。',[C('home.s3','自然与栖息地','The marsh is home to thousands of migrating birds that stop there to feed before crossing the mountains.','这片湿地是数千只候鸟的栖息地，它们会在越过群山前停下来觅食。','The marsh is home to thousands of migrating birds / that stop there to feed / before crossing the mountains.','be home to 表示是……的栖息地；that 从句描述鸟类行为。','湿地为候鸟提供栖息和觅食场所，体现 s3。'),C('home.s5','回家与方向','After the late shift, Pavel walked home through the quiet streets instead of waiting for another bus.','晚班结束后，帕维尔穿过安静的街道步行回家，没有继续等下一班公交。','After the late shift / Pavel walked home through the quiet streets / instead of waiting for another bus.','home 作副词表示朝家里去，前面通常不加 to。','walked home 描述回家的方向，体现副词义。')],M('After the game, the team walked to home to celebrate in their own houses.','After the game, the team walked home to celebrate in their own houses.','home 作方向副词时通常不与 to 连用。','grammar'),[Q('home',1,1,'Your home is usually?','the place where you live','the office where you work once','a road sign near a station','home 名词常指居所。'),Q('home',2,2,'Someone’s home town is the place where they?','grew up or come from','will travel only next year','keep their car keys','home town 指故乡。'),Q('home',3,4,'A home game is played?','by a team at its own venue','only in a family kitchen','at a neutral airport','home 作定语可指主场的。'),Q('home',4,5,'“She went home” means she went?','to the place where she lives','to a public office called “Home”','to a place away from her residence','home 作副词表示回家。')]);
P('home guard','Home guard 是 home 与 guard 组成的名词短语，指在本国境内守卫的志愿民防或国土防卫队伍。',C('home guard.s1','民防与国土守卫','During the emergency, the home guard helped direct residents away from the coast while regular troops secured the port.','紧急状态期间，国民警卫队协助引导居民远离海岸，同时正规军守卫港口。','During the emergency / the home guard helped direct residents away from the coast / while regular troops secured the port.','home guard 指守卫本土的队伍；while 对比两支力量的任务。','队伍在本国境内协助防卫和疏散。'),M('The home guard protected a foreign country while leaving its own homeland undefended.','The home guard helped defend its own country during the emergency.','home guard 的职责指向本国防卫。'),[Q('home guard',1,1,'A home guard is organized mainly to?','defend or protect its own country','sell homes to travelers','manage a company’s head office','home guard 指本土防卫队伍。'),Q('home guard',2,1,'During a crisis, a home guard might?','help protect local communities and territory','raise money for a hockey league only','inspect every household’s cooking','守卫本土的队伍可协助社区安全。'),Q('home guard',3,1,'The word home in home guard points to?','one’s own country or homeland','a private kitchen','a holiday resort','home 在此指本国。'),Q('home guard',4,1,'A home guard differs from a household guard because it?','serves a wider national or territorial defense role','works only as a domestic cleaner','guards a single person’s hat','该词指本土防卫组织。')]);
P('home loan','Home loan 是 home 与 loan 组成的金融名词短语，指用于购买住宅的贷款，通常以所购住房作抵押。',C('home loan.s1','住房金融','The couple compared interest rates and monthly payments before signing a home loan for their first apartment.','这对夫妇在为第一套公寓签订住房贷款前，比较了利率和月供。','The couple compared interest rates and monthly payments / before signing a home loan / for their first apartment.','home loan 指购房贷款；before 从句说明签署前的比较步骤。','贷款用于购买第一套住房，符合词义。'),M('The bank issued a home loan to pay for the family’s weekly groceries.','The bank issued a home loan to help the family buy an apartment.','home loan 用于购房，不是日常食品开销。'),[Q('home loan',1,1,'A home loan is borrowed mainly to?','buy a house or apartment','pay for a week of groceries','purchase a train ticket','home loan 指住房贷款。'),Q('home loan',2,1,'Before taking a home loan, buyers often compare?','interest rates and repayment terms','the color of every neighbor’s car','the lyrics of a song','贷款利率和还款条件会影响成本。'),Q('home loan',3,1,'A lender’s monthly home-loan payment usually repays?','part of the borrowed amount and interest','the entire price of a bus ticket','a landlord’s grocery bill','月供偿还本金及利息。'),Q('home loan',4,1,'Which item is closely related to a home loan?','mortgage repayments','hockey equipment','a haystack','住房抵押还款与 home loan 相关。')]);
P('homeland','Homeland 由 home 与 land 组合，指一个人的祖国或本国，也可指某民族长期居住、认同的传统家园。',C('homeland.s2','民族与文化','The elders taught the children the songs and place names of their ancestral homeland, even after the community moved abroad.','即使社区迁居海外，长者仍教孩子们唱祖先故乡的歌、记住当地地名。','The elders taught the children the songs and place names / of their ancestral homeland / even after the community moved abroad.','homeland 指民族传统家园；ancestral 表示祖先世代生活的地方。','社区迁居后仍传承原乡文化，体现民族故乡义。'),M('The community called a place with no historical or cultural link its ancestral homeland.','The community called the region where its ancestors had lived its ancestral homeland.','没有历史或文化联系的地方不应称为祖先家园。'),[Q('homeland',1,1,'A person’s homeland is often?','the country they were born in or belong to','the first office where they worked','a town they visited once on holiday','homeland 可指祖国、本国。'),Q('homeland',2,2,'A people’s traditional homeland is?','the land with which that group has a long historical connection','any empty field they have never seen','a temporary hotel room abroad','也可指民族传统家园。'),Q('homeland',3,1,'Why might emigrants preserve homeland songs?','the songs connect them with their culture and origins','the songs prove they own every foreign city','the songs replace all family memories','故乡歌曲承载文化认同。'),Q('homeland',4,1,'Which phrase is natural?','return to their ancestral homeland','borrow a homeland from a bank','headquarter a homeland at sea','ancestral homeland 指祖先家园。')]);
P('homeless','Homeless 由 home 加否定后缀 -less 构成，形容没有固定住所的人或群体。',C('homeless.s1','社区援助','The shelter opened its doors during the cold snap and offered homeless residents warm meals and a safe place to sleep.','寒潮期间，收容所开放大门，为无家可归的居民提供热饭和安全的睡觉场所。','The shelter opened its doors during the cold snap / and offered homeless residents / warm meals and a safe place to sleep.','homeless 作形容词修饰 residents；and 连接收容所提供的两种帮助。','没有固定住所并需临时庇护的人符合 homeless。'),M('The homeless family had a permanent home and never needed temporary shelter.','The homeless family had no permanent home and stayed at a temporary shelter.','已有固定住所且不需要庇护，与 homeless 相矛盾。'),[Q('homeless',1,1,'A homeless person is someone who?','does not have a permanent place to live','has several houses available','is visiting a friend for one afternoon','homeless 指没有固定住所。'),Q('homeless',2,1,'A city may help homeless residents by providing?','shelter and access to support services','fines for sleeping in their own homes','a new house key to every tourist','临时庇护和支持服务可帮助无家可归者。'),Q('homeless',3,1,'The suffix -less in homeless means?','without or lacking','full of','able to make','-less 表示缺乏 home。'),Q('homeless',4,1,'Which phrase is respectful and clear?','people experiencing homelessness','people who chose to lose every home','owners of multiple houses','该表达准确指没有住所的人群。')]);
P('homely','Homely 由 home 加 -ly 构成，英式英语可指朴实舒适、不讲究奢华；另一个较旧的用法可指外貌不出众。',C('homely.s1','居家氛围','The homely kitchen smelled of fresh bread, with mismatched chairs around a table worn smooth by family meals.','这间朴实温馨的厨房飘着新鲜面包香，磨得光滑的桌子旁摆着几把不同的椅子。','The homely kitchen smelled of fresh bread / with mismatched chairs / around a table worn smooth by family meals.','homely 修饰 kitchen，强调朴实、舒适而非精致奢华。','面包香和经常使用的家具构成温馨家常氛围。'),M('The homely cottage was described as cold, sterile, and entirely without signs of anyone living there.','The homely cottage felt warm and lived-in, with books and blankets in every room.','有人居住的温馨质感与冷清无生气的描写相反。'),[Q('homely',1,1,'In British English, a homely room is often?','simple, comfortable, and welcoming','luxurious and formally decorated','empty and impossible to enter','homely 常表示朴实舒适。'),Q('homely',2,2,'In an older sense, a homely face may be described as?','not especially attractive','perfectly symmetrical and glamorous','hidden behind a mask','该词也可有外貌不出众的旧义。'),Q('homely',3,1,'Which setting feels homely?','a small kitchen with familiar furniture and warm food','a sterile room with no personal objects','a palace hall prepared for a formal state banquet','熟悉、舒适的厨房更有家常感。'),Q('homely',4,1,'Why can homely need context?','it may praise comfort in one use but describe plain looks in another','it always means exactly “homeless”','it is a verb for building houses','英式赞许义与外貌义需结合语境区分。')]);
P('homemade','Homemade 由 home 与 made 组合，形容在家里或小作坊自制、而非工厂批量生产的东西。',C('homemade.s1','烹饪与礼物','Rosa brought homemade plum jam to the picnic, using fruit from her garden and jars she had sterilized herself.','罗莎带了自制李子酱去野餐，用的是自家果园的水果和她亲自消毒的罐子。','Rosa brought homemade plum jam to the picnic / using fruit from her garden / and jars she had sterilized herself.','homemade 修饰 jam，说明它是自家制作；using 补充原料来源。','果园水果和亲手处理的罐子体现自制。'),M('The homemade bread came sealed from a large factory production line and had never been prepared at home.','The homemade bread was mixed and baked in Rosa’s kitchen.','工厂批量生产、从未在家制作的面包不符合 homemade。'),[Q('homemade',1,1,'Homemade jam is?','made at home rather than bought as factory-made','made only from imported metal','a recipe written by a restaurant critic','homemade 指家中自制。'),Q('homemade',2,1,'Which item is homemade?','a scarf knitted by its owner at home','a mass-produced scarf from a warehouse','a scarf designed but never made','在家亲手织成的围巾是 homemade。'),Q('homemade',3,1,'The word homemade most directly combines?','home and made','honey and meadow','holiday and market','该词由 home 与 made 组合。'),Q('homemade',4,1,'A homemade gift often shows that someone?','made it personally instead of buying a factory product','ordered it anonymously from a large factory','borrowed it without asking','自制礼物通常是亲手制作的。')]);
P('homemaker','Homemaker 由 home、make 与施事后缀 -er 构成，指负责管理家庭日常事务的人。',C('homemaker.s1','家庭生活','As the family’s homemaker, Priya coordinated meals, repairs, school forms, and care for her elderly father.','作为家中的持家者，普丽娅统筹膳食、维修、学校表格以及照料年迈父亲等事务。','As the family’s homemaker / Priya coordinated meals, repairs, school forms, / and care for her elderly father.','homemaker 指承担家庭管理工作的人；as 引出角色身份。','统筹家庭日常事务体现持家者的职责。'),M('The homemaker was responsible for running the household but never arranged any meals, care, or home tasks.','The homemaker organized meals, household tasks, and family care.','负责管理家庭却完全不处理家务事务，前后不符。'),[Q('homemaker',1,1,'A homemaker is a person who?','manages the practical work of a household','builds highways for a living','sells houses at an estate office','homemaker 指管理家庭事务的人。'),Q('homemaker',2,1,'Which task might a homemaker coordinate?','meals, repairs, and household schedules','the launch of a satellite','a newspaper’s sports headlines','家庭生活安排是持家者的工作内容。'),Q('homemaker',3,1,'Does homemaker necessarily mean a person is unpaid?','No; the word describes a household role, not a pay status.','Yes; it always means the person has no income.','Yes; it means the person owns several houses.','词义指家庭角色，不限定是否有收入。'),Q('homemaker',4,1,'The suffix -maker in homemaker points to?','someone who makes or manages a home','a device that measures health','a person who sells honey','homemaker 由管理家庭的含义构成。')]);
P('homemaking','Homemaking 由 home 与 making 组合，指管理家庭所需的日常技能和工作，如安排膳食、清洁和照护。',C('homemaking.s1','生活技能','The community course teaches homemaking skills such as planning a budget, preparing meals, and safely storing food.','社区课程教授理家技能，例如规划预算、准备饭菜和安全储存食物。','The community course teaches homemaking skills / such as planning a budget, preparing meals, / and safely storing food.','homemaking 作名词修饰 skills；such as 后列举具体家务技能。','预算、烹饪和储物都是运行家庭的日常任务。'),M('The homemaking class taught no household skills and focused only on repairing aircraft engines.','The homemaking class taught budgeting, meal preparation, and household care.','飞机发动机维修不属于理家技能课程内容。'),[Q('homemaking',1,1,'Homemaking involves skills for?','running and caring for a household','managing an airline’s flight schedule','building a sports stadium','homemaking 指理家及家庭管理。'),Q('homemaking',2,1,'Which lesson belongs in a homemaking course?','planning meals and keeping food safely','calculating a rocket’s escape velocity','designing a hockey league logo','膳食与食品储存是家庭技能。'),Q('homemaking',3,1,'Homemaking is related to the role of a?','homemaker','hitter','haulier','homemaking 与 homemaker 同属家庭管理词汇。'),Q('homemaking',4,1,'The noun homemaking names?','the tasks and skills involved in running a home','a holiday taken by a new employee','a company’s financial holdings','该名词指管理家庭的工作和技能。')]);
P('homeostasis','Homeostasis 由希腊语 homoios“相似”与 stasis“稳定状态”构成，指生物体维持内部环境相对稳定的能力。',C('homeostasis.s1','生理学','Sweating helps maintain homeostasis by cooling the body when its internal temperature rises during exercise.','运动时体内温度升高，出汗通过给身体降温帮助维持内稳态。','Sweating helps maintain homeostasis / by cooling the body / when its internal temperature rises during exercise.','homeostasis 指内部环境稳定；by 引出出汗发挥作用的方式。','体温调节使内部状态保持在稳定范围内。'),M('The body maintained homeostasis by allowing its temperature to rise without limit.','The body maintained homeostasis by regulating temperature within a narrow range.','不受限制地升温无法维持内部稳定。'),[Q('homeostasis',1,1,'Homeostasis is the maintenance of?','a relatively stable internal state','constant external weather','a household’s monthly budget','homeostasis 指内环境稳定。'),Q('homeostasis',2,1,'Which response helps preserve homeostasis?','sweating when body temperature gets too high','letting blood sugar rise without control','stopping all regulation of body temperature','出汗有助于调节体温。'),Q('homeostasis',3,1,'Homeostasis is important because it helps an organism?','keep internal conditions within workable limits','change its species every season','avoid using energy at all','稳定内部环境使生理过程正常运行。'),Q('homeostasis',4,1,'The term is often used in discussions of?','physiology and biological regulation','newspaper page headings','roadside hitchhiking','homeostasis 是生理调节术语。')]);
P('homeotherm','Homeotherm 由表示“相同”的希腊语词素与 therm“热”相关成分组成，指能把体温维持在较窄范围内的恒温动物。',C('homeotherm.s1','动物生理','A homeotherm keeps its internal temperature within a narrow range even when the air outside becomes much colder.','即使外界气温明显下降，恒温动物也会把体内温度维持在较窄范围内。','A homeotherm keeps its internal temperature within a narrow range / even when the air outside / becomes much colder.','homeotherm 是动物名词；even when 引出外界条件变化。','体内温度对外界寒冷保持相对稳定，符合恒温动物定义。'),M('The biologist called a lizard a homeotherm because its body temperature always matched the changing air temperature.','The biologist called a bird a homeotherm because it maintained a stable internal temperature.','体温随环境改变的动物不符合恒温动物的定义。'),[Q('homeotherm',1,1,'A homeotherm keeps its body temperature?','within a relatively narrow range','exactly equal to the air at every moment','permanently below freezing','homeotherm 指能稳定体温的动物。'),Q('homeotherm',2,1,'Which animal is commonly a homeotherm?','a bird','a lizard whose temperature tracks the sun','a fish whose body temperature varies with water','鸟类通常属于恒温动物。'),Q('homeotherm',3,1,'A homeotherm differs from many reptiles because it?','regulates internal temperature more steadily','has no need for food','cannot move in cold weather','恒温动物调节体温，不完全随环境变化。'),Q('homeotherm',4,1,'The root therm in homeotherm relates to?','heat or temperature','home ownership','a written sermon','therm 与热、温度有关。')]);
P('homeownership','Homeownership 由 home、owner 与 -ship 构成，指拥有住房的状态或房屋所有权。',C('homeownership.s1','住房政策','The survey found that rising prices had delayed homeownership for many first-time buyers.','调查发现，房价上涨使许多首次购房者推迟了拥有住房的计划。','The survey found / that rising prices had delayed homeownership / for many first-time buyers.','homeownership 是抽象名词，指购房并拥有住宅的状态。','首次买家因房价上涨而推迟拥有住房，符合词义。'),M('The report said homeownership increased even though every resident rented and nobody owned a house.','The report said homeownership increased as more residents bought their homes.','所有人都租房与房屋所有权增加相矛盾。'),[Q('homeownership',1,1,'Homeownership means?','the state of owning one’s dwelling','the habit of borrowing a neighbor’s tools','the management of a school','homeownership 指自有住房状态。'),Q('homeownership',2,1,'A policy that supports homeownership may help people?','buy and own a home','rent a hotel room for one night','sell every household appliance','支持购房的政策促进住房所有权。'),Q('homeownership',3,1,'Which person has homeownership?','someone whose house they own','a tenant renting a room month to month','a traveler staying in a hostel','房屋所有者拥有 homeownership。'),Q('homeownership',4,1,'The suffix -ship here forms a noun for?','a state or condition','a person who sails a boat','a place to store honey','-ship 表示状态或身份。')]);
P('homepage','Homepage 是互联网早期形成的 home 与 page 复合词，指网站的首页或用户打开网站时首先看到的主要页面。',C('homepage.s1','网络导航','The library’s homepage lists opening hours, a search box, and links to the catalog and digital archives.','图书馆主页列出开放时间、搜索框，以及通往目录和数字档案的链接。','The library’s homepage lists opening hours, a search box, / and links / to the catalog and digital archives.','homepage 指网站首页；lists 后并列首页展示的内容。','网站入口页面包含主要导航和信息。'),M('The homepage was the last hidden page of the site, accessible only after leaving the website.','The homepage was the main page visitors saw when they opened the site.','离开网站后才可访问的末页不是网站首页。'),[Q('homepage',1,1,'A website homepage is usually?','its main or opening page','a page stored only on a printer','the last page of a paper book','homepage 指网站主页。'),Q('homepage',2,1,'A visitor might use a homepage to?','find the site’s sections and main links','measure the speed of a train','replace the computer’s keyboard','首页常提供网站导航。'),Q('homepage',3,1,'Which item belongs on a library homepage?','a catalog search link','a private bank password for every reader','a list of unrelated road hazards','目录搜索链接适合放在图书馆主页。'),Q('homepage',4,1,'The word homepage combines?','home and page','hockey and page','honey and postage','该词由 home 与 page 组合。')]);
P('homesick','Homesick 由 home 与 sick 组合，指离家在外时因想念家人、住所或熟悉环境而感到难过。',C('homesick.s2','文化与思乡','After moving overseas, Lina felt homesick for the language, familiar meals, and festivals she had grown up with.','移居海外后，莉娜怀念成长过程中熟悉的语言、饭菜和节日，感到思乡。','After moving overseas / Lina felt homesick for the language, familiar meals, and festivals / she had grown up with.','homesick for 后接所思念的事物；for 并不限于住宅本身。','她想念故土文化和生活习惯，体现扩展义。'),M('He felt homesick because he was surrounded by his family, familiar food, and his own home.','He felt homesick because he missed his family and familiar home while abroad.','身处熟悉家人和住所之中，不符合离家思乡的原因。'),[Q('homesick',1,1,'A homesick student feels sad because they?','miss home while away','are ill from eating too much honey','have lost their school homework','homesick 指因离家而难过。'),Q('homesick',2,2,'Someone may be homesick for?','the food and language of their home culture','a company’s stock portfolio','a road sign they saw once','可思念故土文化习惯。'),Q('homesick',3,1,'Which situation could make a person homesick?','living abroad and missing family traditions','returning to a familiar room after one hour','buying a new home in their hometown','远离家人和传统会引发思乡。'),Q('homesick',4,2,'Homesick is formed from?','home plus sick','honey plus comb','head plus strong','该词由 home 与 sick 组合。')]);
P('homespun','Homespun 由 home 与 spun 组合，作形容词可指家中纺织的布或朴实、不加修饰的风格；作名词指家织土布。',C('homespun.s2','纺织与材料','The museum displayed homespun woven from local wool, with uneven threads that showed it had been made by hand.','博物馆展出用本地羊毛织成的土布，参差的纱线显出它是手工制作的。','The museum displayed homespun woven from local wool / with uneven threads / that showed it had been made by hand.','homespun 作名词指家织布；woven from 说明原料。','本地羊毛手织而成的布对应名词义。'),M('The museum labeled a factory-made synthetic sheet homespun even though no one had spun or woven it at home.','The museum labeled the hand-spun local wool cloth homespun.','工厂合成布不是家中纺织的土布。'),[Q('homespun',1,1,'Homespun advice is usually?','plain, practical, and unpolished','highly technical and full of equations','secretly copied from a legal contract','形容词可表示朴实、不加修饰。'),Q('homespun',2,2,'As a noun, homespun is?','cloth spun or woven at home','a modern plastic coating','a kind of household loan','名词 homespun 指土布。'),Q('homespun',3,1,'Which object could be homespun?','a rough wool blanket woven by hand at home','a mass-produced synthetic sheet','a steel cooking pot from a factory','手工家织的羊毛毯可称 homespun。'),Q('homespun',4,1,'The element spun in homespun relates to?','making thread by twisting fibers','spending a vacation abroad','hearing a courtroom case','spun 与纺纱有关。')]);
P('homestay','Homestay 由 home 与 stay 组合，指旅行者或学生住在当地接待家庭中的住宿安排。',C('homestay.s1','旅行与寄宿','During her language course, Mei chose a homestay with a local family instead of renting a room in a hotel.','梅在语言课程期间选择住在当地家庭，而不是租住酒店客房。','During her language course / Mei chose a homestay with a local family / instead of renting a room in a hotel.','homestay 指寄宿在接待家庭；with a local family 说明住宿形式。','住进当地家庭而非酒店对应 homestay。'),M('The student booked a homestay but slept alone in a locked hotel room with no host family.','The student booked a homestay and stayed with a local host family.','独自住酒店、没有接待家庭，不属于 homestay。'),[Q('homestay',1,1,'A homestay usually means?','staying with a local host family','sleeping in a tent without a host','renting a whole office building','homestay 指家庭寄宿。'),Q('homestay',2,1,'A student might choose a homestay to?','experience local daily life while studying','avoid meeting any local people','buy a house during a short course','寄宿家庭提供接触当地生活的机会。'),Q('homestay',3,1,'Which lodging is a homestay?','a room in a family’s home with the hosts present','a private room in an airport terminal','a tent in an unstaffed campground','与接待家庭同住是 homestay。'),Q('homestay',4,1,'Homestay differs from a hotel stay because it involves?','accommodation with a host household','a longer flight route','a required medical examination','关键区别是住在接待家庭。')]);
P('homestead','Homestead 源自古英语 hamstede（家园、居住地），指家庭农庄及其住宅和附属土地。',C('homestead.s1','乡村生活','The old homestead included a farmhouse, a barn, and several fields that had supported the same family for generations.','这座老农庄包括一栋农舍、一座谷仓和几片田地，世世代代养活着同一家人。','The old homestead included a farmhouse, a barn, and several fields / that had supported the same family / for generations.','homestead 指农庄整体；included 后并列住宅和土地设施。','住宅与附属田地长期共同构成家庭农庄。'),M('The family called a rented city hotel room their homestead even though they owned no land or house there.','The family’s homestead was their farmhouse and the land surrounding it.','短期租住的酒店房间不是家庭农庄。'),[Q('homestead',1,1,'A homestead usually includes?','a home and the land belonging to a family farm','only a hotel room for one night','a company’s central office','homestead 指农庄及住宅土地。'),Q('homestead',2,1,'Which property is a homestead?','a farmhouse with barns and fields','a rented desk in a city office','a ship’s covered hatchway','农舍、谷仓和田地组成农庄。'),Q('homestead',3,1,'A homestead is most closely associated with?','a family dwelling and farm land','a courtroom hearing','a crowded subway station','它常与家庭农场有关。'),Q('homestead',4,1,'The word homestead combines the idea of home with?','a place or site','a medical treatment','a type of sports score','词素表达居住地点。')]);
P('homesteader','Homesteader 由 homestead 加施事后缀 -er 构成，指通过拓垦、申领土地并建家园而定居的人。',C('homesteader.s1','开拓与定居','The homesteader built a cabin, cleared a small field, and filed the land claim before winter arrived.','这位拓荒定居者在冬天来临前建了小屋、清出一块田地，并提交土地申请。','The homesteader built a cabin, cleared a small field, / and filed the land claim / before winter arrived.','homesteader 指开垦土地并在其上定居的人；并列动词展示行动。','建屋、耕地、申领土地体现拓荒定居。'),M('The homesteader abandoned the land before building a home or claiming any property there.','The homesteader claimed a plot and built a home on it.','未定居或申领土地，不符合 homesteader 的身份。'),[Q('homesteader',1,1,'A homesteader is someone who?','claims land and establishes a home or farm','manages a city theater','sells home loans at a bank','homesteader 指拓荒定居者。'),Q('homesteader',2,1,'Which person is a homesteader?','a settler who clears land and builds a cabin','a tourist staying one night in a hotel','a homeowner renting an apartment in a city','在新土地开垦并建家的人符合此义。'),Q('homesteader',3,1,'The suffix -er in homesteader identifies?','a person who settles a homestead','a condition of being homesick','a place to store hay','-er 表示实施定居的人。'),Q('homesteader',4,1,'A homesteader’s work might include?','building a dwelling and cultivating a plot','writing a headline for a newspaper','repairing an airport runway','建屋和开垦耕地是拓荒活动。')]);
P('hometown','Hometown 由 home 与 town 组合，指一个人来自或长期认作故乡的城镇。',C('hometown.s1','故乡与归属','Although she had lived abroad for a decade, Nora still called the coastal town her hometown and returned each summer.','尽管诺拉已在国外生活十年，她仍把那座海滨小镇称为故乡，并每年夏天回去。','Although she had lived abroad for a decade / Nora still called the coastal town her hometown / and returned each summer.','hometown 指个人来自的城镇；call A B 将 town 称为 hometown。','长期离乡仍认同并定期返回，符合故乡义。'),M('He called the airport he visited once on a layover his hometown, although he had never lived there.','He called the town where he grew up his hometown.','只短暂停留过的机场并非通常意义上的故乡。'),[Q('hometown',1,1,'A person’s hometown is usually the place?','they come from or grew up in','where they bought lunch yesterday','where their company stores its shares','hometown 指一个人的故乡城镇。'),Q('hometown',2,1,'Someone returning to their hometown is returning to?','the town they regard as home','a random town chosen by a train','the first city listed on a map','回到 hometown 即回故乡。'),Q('hometown',3,1,'Which statement fits hometown?','She grew up there and still calls it home.','She changed trains there once and forgot its name.','She has never visited it.','成长并认同的地方符合 hometown。'),Q('hometown',4,1,'The word hometown combines home with?','town','loan','honey','该词由 home 与 town 组合。')]);
P('homewards','Homewards 由 home 与方向后缀 -ward(s) 构成，作副词表示朝家或故乡方向前进，常见于英式英语。',C('homewards.s1','行程方向','As daylight faded, the hikers turned homewards toward the village where their car was parked.','天色渐暗，徒步者转向回家的方向，朝着停车所在的村庄走去。','As daylight faded / the hikers turned homewards / toward the village / where their car was parked.','homewards 作方向副词，表示朝家走；toward 补充具体目的地。','傍晚折返住所方向，体现 homewards。'),M('The hikers walked homewards by traveling farther away from their home and refusing to turn back.','The hikers walked homewards toward the village where they had started.','朝远离住所的方向走不符合 homewards。'),[Q('homewards',1,1,'To travel homewards is to move?','in the direction of home','away from home without returning','toward a distant workplace only','homewards 表示朝家方向。'),Q('homewards',2,1,'When might a traveler turn homewards?','after finishing the visit and starting back','before leaving home for the first time','while moving deeper into an unfamiliar city','返程时会转向回家。'),Q('homewards',3,1,'Homewards is most similar to?','homeward','homeless','hollow','homeward 同样表示向家。'),Q('homewards',4,1,'The suffix -wards helps express?','a direction of movement','a person who performs an action','the plural of a household','-wards 常构成方向副词。')]);
P('homework','Homework 由 home 与 work 组合，指学生在家完成的课业，也可指事前做的研究或准备。',C('homework.s2','准备与研究','Before the interview, the reporter did her homework on the company’s history and prepared questions about its safety record.','采访前，记者研究了这家公司的历史，并准备了有关安全记录的问题。','Before the interview / the reporter did her homework on the company’s history / and prepared questions about its safety record.','do one’s homework 可比喻做足功课、事先研究。','采访前查资料并准备问题，体现准备研究义。'),M('The reporter did her homework by arriving with no information and refusing to prepare any questions.','The reporter did her homework by researching the company before the interview.','毫无准备与“事先做好研究”相反。'),[Q('homework',1,1,'A pupil’s homework is?','schoolwork assigned to be done outside class','a paid job at a company office','a family’s mortgage payment','homework 常指课外作业。'),Q('homework',2,2,'“Do your homework before the meeting” can mean?','research and prepare in advance','complete a worksheet in class only','leave all questions unanswered','比喻义指提前研究准备。'),Q('homework',3,1,'Which is an example of homework?','solving assigned problems at home','taking a school holiday','repairing a teacher’s car','学生回家完成的作业是 homework。'),Q('homework',4,2,'A journalist’s homework for an interview might include?','checking public records and company history','memorizing an unrelated song','ignoring the interview subject','事先查阅资料属于准备工作。')]);
P('homicide','Homicide 源自拉丁语 homicidium（杀人），在法律和新闻语境中指一个人导致另一个人死亡的行为或案件。',C('homicide.s1','法律与案件','Detectives treated the death as a possible homicide and waited for forensic results before making a public statement.','侦探把这起死亡事件视作可能的杀人案，并在公开表态前等待法医结果。','Detectives treated the death as a possible homicide / and waited for forensic results / before making a public statement.','homicide 是正式案件名词；possible 表明调查尚未定论。','有他人致死的可能，调查人员因此按案件处理。'),M('The report classified the death as homicide even though it confirmed that no person had caused it.','The report classified the death as homicide after evidence showed that another person caused it.','确认无人导致死亡，与 homicide 的基本定义不符。'),[Q('homicide',1,1,'Homicide means?','the killing of one person by another','a person’s natural sleep cycle','a disagreement about a home loan','homicide 指杀人。'),Q('homicide',2,1,'A homicide detective investigates?','a death that may have been caused by another person','a lost package at a railway station','the history of a school holiday','杀人侦探调查可能由他人造成的死亡。'),Q('homicide',3,1,'Does homicide by itself always mean murder?','No; the legal classification depends on circumstances and law.','Yes; every homicide has identical legal status.','No; it only means a person moved house.','homicide 是更广的法律类别，定性取决于案情。'),Q('homicide',4,1,'The Latin element homo in homicide refers to?','a human being','honey','a home','homo 指人。')]);
P('homily','Homily 经拉丁语、希腊语 homilia“谈话、讲论”进入英语，指宗教讲道，也可泛指带有道德劝诫意味的说教。',C('homily.s1','宗教与劝诫','The minister’s short homily urged the congregation to forgive one another and care for neighbors in need.','牧师简短的讲道劝会众彼此宽恕，并照顾有需要的邻居。','The minister’s short homily / urged the congregation / to forgive one another and care for neighbors in need.','homily 指讲道或道德训诫；urge sb to do 引出劝勉内容。','宗教场合中的道德劝勉符合讲道义。'),M('The minister’s homily contained no speech or moral message because it was a silent painting.','The minister delivered a homily about forgiveness and care for neighbors.','无言的画作不是讲道或口头训诫。'),[Q('homily',1,1,'A homily is usually?','a sermon or moral lecture','a written home-loan contract','a loud cry from across a field','homily 指讲道或说教。'),Q('homily',2,1,'A speaker giving a homily may urge listeners to?','act with compassion and moral care','buy a particular hockey stick','ignore every ethical question','道德讲论会劝人行善。'),Q('homily',3,1,'A long homily about punctuality would most likely be?','a lecture urging people to be on time','a train delay caused by a signal','a list of ticket holders','homily 也可泛指道德训诫。'),Q('homily',4,1,'The word homily is most closely linked to?','sermon or moral advice','sports statistics','a garden tool','homily 与讲道、道德劝告有关。')]);
P('homing','Homing 来自 home 加 -ing，可作形容词表示能返回起点或目标，也可作名词指动物或设备的归航、定向返回能力。',C('homing.s2','动物导航','The researchers studied the pigeon’s homing after releasing it hundreds of kilometers from its loft.','研究人员把鸽子放飞到距离鸽舍数百公里的地方后，研究它的归巢能力。','The researchers studied the pigeon’s homing / after releasing it / hundreds of kilometers from its loft.','homing 作名词指返回熟悉地点的能力；after 引出测试条件。','鸽子远距离后返回鸽舍，体现归巢能力。'),M('The homing pigeon had no ability to return and became more lost every time it flew.','The homing pigeon used its homing ability to return to its loft.','完全没有返回能力与 homing pigeon 的特征相反。'),[Q('homing',1,1,'A homing device is designed to?','find or return to a target or starting point','prevent any signal from being sent','measure the weight of a household','homing 形容可定向返回。'),Q('homing',2,2,'A pigeon’s homing is its ability to?','find its way back to its loft','build a hive for bees','hear a distant musical note','homing 作名词指归巢能力。'),Q('homing',3,1,'A homing signal helps a vehicle?','navigate toward a designated target','turn into a house','avoid receiving all directions','定向信号引导设备前往目标。'),Q('homing',4,2,'Which animal is famous for homing?','a pigeon returning to its loft','a fish staying in one aquarium corner','a horse that has never left its stable','鸽子以归巢能力著称。')]);
P('hominid','Hominid 经现代生物学用语发展而来，指人科成员，包括人类及早期近人类；在化石研究中也可特指古人类祖先。',C('hominid.s2','古人类化石','The museum displayed a hominid fossil beside a timeline showing how early human ancestors changed over millions of years.','博物馆把一件古人类化石陈列在时间轴旁，展示早期人类祖先在数百万年间的变化。','The museum displayed a hominid fossil / beside a timeline / showing how early human ancestors changed over millions of years.','hominid 指人科成员或化石中的古人类祖先；fossil 明确聚焦古生物义。','展出的化石属于早期人类祖先，符合 s2。'),M('The exhibit labeled a modern house cat a hominid because it lived in the same museum.','The exhibit labeled an early human ancestor fossil a hominid.','同处一个博物馆不能使猫成为人科动物。'),[Q('hominid',1,1,'In biological classification, a hominid belongs to the family that includes?','humans and their close great-ape relatives','all insects that live in homes','only modern birds','hominid 指人科成员。'),Q('hominid',2,2,'A hominid fossil usually represents?','an early human or human-like ancestor','a modern fish with no bones','a plant seed from a garden','化石义指古人类祖先。'),Q('hominid',3,1,'Which museum object could be a hominid fossil?','an ancient human-like skull found in rock','a newly made plastic model of a hawk','a fossilized leaf from a fern','早期近人类遗骸可称 hominid fossil。'),Q('hominid',4,1,'The suffix -id in hominid helps form a term for?','a member of a biological group','a place to store household goods','a person who sells fruit in a street','该词指生物学类群成员。')]);
P('hominoid','Hominoid 由表示人类与猿类的词根和 -oid“类似、属于某类”构成；可作名词指人猿总科动物，也可作形容词表示与人猿相关。',C('hominoid.s2','分类学用语','The paper used hominoid anatomy to compare shoulder movement in humans and other apes.','论文用人猿类解剖特征比较人类与其他猿类的肩部活动。','The paper used hominoid anatomy / to compare shoulder movement / in humans and other apes.','hominoid 作形容词修饰 anatomy，指人猿类的解剖特征。','比较人类和猿类共同的身体特征，体现形容词义。'),M('The researcher called a butterfly hominoid because it was a member of the ape group.','The researcher called a gibbon a hominoid because it belongs to the ape group.','蝴蝶不是人猿总科灵长动物。'),[Q('hominoid',1,1,'As a noun, a hominoid is a primate group that includes?','humans and apes such as gibbons','all insects and spiders','only fish that live in rivers','hominoid 名词指人猿总科动物。'),Q('hominoid',2,2,'Hominoid anatomy is anatomy?','relating to humans and apes','relating only to flowering plants','relating to the inside of a home','形容词 hominoid 指人猿相关的。'),Q('hominoid',3,1,'Which animal is a hominoid?','a gibbon','a hawk','a honeybee','长臂猿属于人猿总科。'),Q('hominoid',4,2,'The suffix -oid often means?','resembling or belonging to a type','without any connection to a type','a place where a type is kept','-oid 表示类似或属于某类。')]);
P('homogeneous','Homogeneous 来自希腊语 homogenēs（同一种类），形容各处同类同质，也可指混合物成分均匀一致。',C('homogeneous.s2','化学与材料','The laboratory produced a homogeneous solution by stirring the powder until no particles remained visible.','实验室持续搅拌粉末，直到看不见颗粒，制成了均匀溶液。','The laboratory produced a homogeneous solution / by stirring the powder / until no particles remained visible.','homogeneous 修饰 solution，表示成分均一；until 从句描述混合终点。','看不到分离颗粒说明溶液均匀。'),M('The mixture was homogeneous because oil and water formed two clearly separated layers.','The mixture was homogeneous after the ingredients blended into one uniform phase.','分成两层说明混合物不均匀。'),[Q('homogeneous',1,1,'A homogeneous group is made up of members that are?','largely of the same kind or nature','completely unrelated in every respect','all changing their identity each hour','homogeneous 可指同类、同质。'),Q('homogeneous',2,2,'A homogeneous liquid mixture is?','evenly blended throughout','separated into visible layers','made entirely of solid blocks','物质义表示混合均匀。'),Q('homogeneous',3,1,'Which sample is homogeneous?','a uniform solution with no visible separation','oil floating in a distinct water layer','a box containing unrelated objects','均一溶液属于 homogeneous。'),Q('homogeneous',4,1,'The Greek element genos in homogeneous relates to?','kind or type','sound or hearing','a household loan','genos 与种类有关。')]);
P('homogenize','Homogenize 由 homogeneous 加 -ize 构成，表示使物质混合均匀，也可比喻使文化、产品或地区趋于相同。',C('homogenize.s1','食品加工','The dairy plant homogenizes the milk so that cream does not separate and rise to the top of the carton.','乳品厂对牛奶进行均质处理，使奶油不会分离并浮到纸盒顶部。','The dairy plant homogenizes the milk / so that cream does not separate / and rise to the top of the carton.','homogenize 作及物动词，表示使混合物成分均一。','处理防止奶油与牛奶分层，体现物质均质义。'),M('The factory homogenized the milk by allowing the cream to separate into a thick layer.','The factory homogenized the milk so the cream remained evenly distributed.','让奶油分层与均质处理的效果相反。'),[Q('homogenize',1,1,'To homogenize milk is to?','make its contents evenly mixed','separate the cream into a distinct layer','freeze it into a block of ice','homogenize 可指使液体均匀。'),Q('homogenize',2,2,'To homogenize regional products can mean to?','make them more alike','make each one increasingly different','remove every product from sale','比喻义是使事物趋同。'),Q('homogenize',3,1,'Which machine may homogenize a substance?','equipment that breaks particles into an even mixture','a scale that only measures weight','a loudspeaker used for announcements','均质机使物质颗粒均匀分散。'),Q('homogenize',4,2,'A company may homogenize its stores by?','making their designs and products look alike','giving every store a unique identity','closing all of its stores','使门店看起来相似是趋同义。')]);
P('homogenous','Homogenous 与 homogeneous 同源，来自希腊语中表示“同一种类”的构词成分，形容组成部分相同或相似。',C('homogenous.s1','群体特征','The sample came from a homogenous population in which all participants shared the same age range and training background.','样本来自一个同质群体，参与者的年龄范围和训练背景都相同。','The sample came from a homogenous population / in which all participants shared / the same age range and training background.','homogenous 修饰 population，说明群体成员的特征相似。','参与者有相同年龄段和背景，体现同质性。'),M('The group was homogenous because every member differed completely in age, training, and experience.','The group was homogenous because its members shared similar training and experience.','所有成员差异极大，与同质群体相反。'),[Q('homogenous',1,1,'A homogenous group consists of members that are?','similar in the relevant ways','all unrelated to one another','assembled at random from every possible category','homogenous 指组成相似。'),Q('homogenous',2,1,'Which classroom could be described as homogenous in age?','one where nearly all students are the same age','one containing people aged five to eighty','one with no students enrolled','年龄相近的班级在该方面同质。'),Q('homogenous',3,1,'Homogenous is often used as a variant of?','homogeneous','hominid','honeyed','homogenous 与 homogeneous 同义相关。'),Q('homogenous',4,1,'A homogenous sample may help researchers?','compare similar participants on a selected measure','guarantee that every result is different','avoid defining who took part','同质样本在特定比较中有用。')]);
P('homonym','Homonym 来自希腊语 homos“相同”与 onyma“名称”，指拼写或读音相同、意义不同的词。',C('homonym.s1','语言与词汇','“Bat” is a homonym because it can name a flying mammal or a club used to hit a ball.','“Bat”是同形异义词，因为它既可指会飞的哺乳动物，也可指击球用的球棒。','“Bat” is a homonym / because it can name a flying mammal / or a club used to hit a ball.','homonym 指同形或同音而意义不同的词；because 后举出两种意义。','同一拼写对应蝙蝠和球棒两个词义。'),M('The words “bat” and “cat” are homonyms because they share no spelling or pronunciation.','The two meanings of “bat” make it a homonym because the spelling is the same.','不同拼写和读音的 bat、cat 并非同形异义词。'),[Q('homonym',1,1,'A homonym is a word that shares spelling or sound with another word but?','has a different meaning','has exactly the same meaning in every use','cannot be spoken aloud','homonym 的要点是形式相同、意义不同。'),Q('homonym',2,1,'“Bat” can mean an animal or sports equipment, so it is a?','homonym','homemaker','hatchway','同一个形式有不同词义。'),Q('homonym',3,1,'What makes two words homonyms?','their spelling or pronunciation matches while meaning differs','their meanings and spelling are both identical','they belong to unrelated languages only','同音或同形且意义不同。'),Q('homonym',4,1,'The Greek element onyma in homonym means?','name','heat','land','onyma 表示名称。')]);
P('homosexual','Homosexual 由表示“相同”的 homo- 与 sexual 构成，可作形容词描述对同性有浪漫或性吸引，也可作名词指有此吸引的人；现代语境中常优先使用 gay、lesbian 或当事人自选称呼。',C('homosexual.s1','词汇与身份','The report used homosexual as an adjective in a historical quotation, while the interviewees described themselves using their own chosen labels.','报告在历史引文中把 homosexual 用作形容词，而受访者用自己选择的称呼描述身份。','The report used homosexual as an adjective / in a historical quotation / while the interviewees described themselves using their own chosen labels.','homosexual 作形容词修饰 attraction 或 relationship；身份称呼应尊重个人选择。','语境区分形容词用法与现代自我称谓偏好。'),M('The article used homosexual as a noun for a person who is attracted only to people of a different sex.','The article used homosexual as a noun for a person attracted to people of the same sex.','对异性的吸引与该词名词义定义相反。'),[Q('homosexual',1,1,'As an adjective, homosexual describes attraction to?','people of the same sex','people of every different species','no person or partner at all','该形容词指对同性的吸引。'),Q('homosexual',2,2,'As a noun in some usage, homosexual refers to?','a person attracted to people of the same sex','a person who studies honeybees','a person who owns a house','名词义指有同性吸引的人。'),Q('homosexual',3,1,'When referring to someone’s identity, a writer should generally?','respect the term the person uses for themself','assign a label without asking','use a medical label in every context','尊重当事人的自我称谓。'),Q('homosexual',4,1,'The prefix homo- in homosexual conveys?','same','home','honey','该前缀表示相同。')]);
P('homosexuality','Homosexuality 由 homosexual 加抽象名词后缀 -ity 构成，指对同性的浪漫或性吸引这一性取向。',C('homosexuality.s1','社会与身份','The documentary discussed the history of homosexuality without treating people’s private lives as a public spectacle.','这部纪录片讨论了同性恋的历史，同时没有把人们的私人生活当作公开奇观。','The documentary discussed the history of homosexuality / without treating people’s private lives / as a public spectacle.','homosexuality 是指性取向的抽象名词；without 引出避免的呈现方式。','讨论历史而尊重个人隐私，符合中性使用。'),M('The textbook defined homosexuality as attraction only to people of a different sex.','The textbook defined homosexuality as romantic or sexual attraction to people of the same sex.','对异性的吸引不是同性恋的定义。'),[Q('homosexuality',1,1,'Homosexuality refers to?','romantic or sexual attraction to people of the same sex','a method for maintaining body temperature','the ownership of a house','homosexuality 指同性吸引的性取向。'),Q('homosexuality',2,1,'A respectful discussion of homosexuality should?','describe people accurately and avoid stereotypes','reduce individuals to a single stereotype','treat private identity as a joke','讨论应避免刻板印象。'),Q('homosexuality',3,1,'The suffix -ity in homosexuality forms?','an abstract noun','a verb meaning to sharpen','a plural for several homes','-ity 构成抽象名词。'),Q('homosexuality',4,1,'Which topic might a history of homosexuality examine?','changes in laws and social attitudes','the storage of honey in a hive','the timing of a train hold-up','相关历史可讨论法律和社会态度。')]);
P('homotherm','Homotherm 由希腊语 homo-“相同”与 therm“热”构成，指能维持相对稳定体温的恒温或温血动物。',C('homotherm.s2','动物分类','The zoology text used homotherm for a warm-blooded animal whose body temperature remains steady despite cooler weather.','动物学教材用 homotherm 指体温能在寒冷天气中保持稳定的温血动物。','The zoology text used homotherm / for a warm-blooded animal / whose body temperature remains steady despite cooler weather.','homotherm 可指温血动物；whose 从句说明体温特征。','无论天气转冷仍维持体温，对应 s2。'),M('The guide called a cold-blooded reptile a homotherm because its body temperature changed with every sunny hour.','The guide called a bird a homotherm because it maintained a steady body temperature.','体温随环境大幅变化的爬行动物不符合恒温定义。'),[Q('homotherm',1,1,'A homotherm maintains?','a relatively steady body temperature','the same temperature as its surroundings at every moment','no internal temperature at all','homotherm 指体温相对稳定的动物。'),Q('homotherm',2,2,'A warm-blooded animal is a homotherm in the sense that it?','keeps its internal temperature within a narrow range','must live only in hot climates','cannot produce body heat','它能够调节并维持体温。'),Q('homotherm',3,1,'Which animal is generally a homotherm?','a mammal','a lizard whose temperature follows the sun','a cold-water fish with changing body temperature','哺乳动物通常是恒温动物。'),Q('homotherm',4,2,'The element therm relates to?','heat and temperature','written names','land ownership','therm 表示热、温度。')]);
P('hone','Hone 的来源尚不确定；作动词可指用磨石磨快刀刃或通过练习磨练技能，名词则指精细磨刀石。',C('hone.s1','技能训练','The interpreter honed her note-taking skills by practicing with recordings that grew faster and more complex each week.','这位口译员通过每周练习越来越快、越来越复杂的录音，磨练了记笔记的技能。','The interpreter honed her note-taking skills / by practicing with recordings / that grew faster and more complex each week.','hone 作动词可指通过练习改进技能；by 引出练习方法。','逐步加大难度以提升技能，符合 s1。'),M('He honed his knife by using a soft cloth that never touched or sharpened the blade.','He honed his knife on a sharpening stone until the edge was fine.','没有接触刀刃的软布不能磨快刀。'),[Q('hone',1,1,'To hone a skill is to?','improve it through careful practice','forget it by avoiding all practice','measure it with a ruler','hone 可指磨练技能。'),Q('hone',2,2,'A hone used by a craftsperson is?','a fine stone for sharpening a blade','a soft cloth for cleaning a table','a container for storing honey','名词 hone 指磨刀石。'),Q('hone',3,1,'Which activity hones a speaker’s public-speaking skill?','rehearsing and refining a talk repeatedly','avoiding every chance to speak','changing the microphone’s color','反复练习能磨练表达技能。'),Q('hone',4,2,'A chef may hone a knife by?','sharpening its edge on a stone','placing it in a bowl of soup','wrapping it in a towel and leaving it','hone 也指磨快刀刃。')]);
P('honest','Honest 经古法语 honest、拉丁语 honestus 进入英语，可指诚实正直、坦率直言或真诚真实。',C('honest.s2','坦率意见','To give an honest assessment, the reviewer praised the design but pointed out that the instructions were confusing.','为了作出坦率评价，评审者既称赞设计，也指出说明书令人困惑。','To give an honest assessment / the reviewer praised the design / but pointed out that the instructions were confusing.','honest 修饰 assessment，表示坦率、不隐瞒真实判断。','评价同时指出优点与问题，体现坦率义。'),M('He gave an honest opinion by concealing his real view and telling the committee only what it wanted to hear.','He gave an honest opinion by stating his real view clearly and fairly.','刻意隐瞒真实看法并迎合听众不符合坦率诚实。'),[Q('honest',1,1,'An honest person is someone who?','tells the truth and does not cheat','steals whenever an opportunity appears','hides every relevant fact','honest 可指诚实正直。'),Q('honest',2,2,'An honest answer may be?','direct and candid, even if uncomfortable','carefully designed to mislead','unrelated to the question','honest 也可指坦率直言。'),Q('honest',3,3,'An honest mistake is?','a genuine error made without intent to deceive','a deliberate fraud planned in advance','a perfectly correct calculation','honest 还可表示真实、非故意造假的。'),Q('honest',4,1,'Which action is honest?','returning a wallet with its cash untouched','keeping the wallet and denying finding it','changing a receipt to claim extra money','归还钱包且未动现金体现诚实。')]);
P('honesty','Honesty 由 honest 加名词后缀 -y 构成，指说实话、不欺骗的品质。',C('honesty.s1','信任与合作','The team valued honesty, so members reported delays early instead of hiding problems until the deadline.','团队看重诚实，因此成员会及早报告延误，而不是把问题藏到截止日期前。','The team valued honesty / so members reported delays early / instead of hiding problems until the deadline.','honesty 是抽象名词，指诚实品质；so 引出这种品质带来的行为。','及时公开问题体现不隐瞒事实。'),M('Her honesty consisted of altering the figures to conceal the project’s overspending.','Her honesty consisted of reporting the overspending accurately.','篡改数字来掩盖超支是欺骗，不是诚实。'),[Q('honesty',1,1,'Honesty is the quality of?','being truthful and not cheating','changing facts to avoid blame','winning every argument','honesty 指诚实。'),Q('honesty',2,1,'Why does honesty help a team?','people can make decisions using accurate information','everyone can hide every delay','no one ever needs to communicate','诚实报告问题帮助团队作判断。'),Q('honesty',3,1,'Which behavior shows honesty?','admitting a mistake before it causes more damage','blaming a colleague for one’s own error','editing records to conceal a loss','主动承认错误体现诚实。'),Q('honesty',4,1,'Honesty is the noun related to?','honest','homely','hollow','honesty 来自 honest。')]);
P('honey','Honey 源自古英语 hunig，名词指蜜蜂制成的甜蜜，也可作亲昵称呼；形容词用法可指蜜色、金黄色。',C('honey.s3','颜色与外观','The wooden floor had a honey glow in the late-afternoon sun, with warm golden tones across the boards.','木地板在午后阳光下泛着蜜黄色光泽，木板上呈现温暖的金色调。','The wooden floor had a honey glow / in the late-afternoon sun / with warm golden tones across the boards.','honey 作定语描述颜色，指像蜂蜜一样的金黄色。','golden tones 对应蜜色的颜色义。'),M('The painter called the deep blue wall honey-colored even though it had no yellow or golden tones.','The painter called the warm golden wall honey-colored.','没有黄色或金色调的深蓝墙不属于蜜色。'),[Q('honey',1,1,'Honey is the sweet substance made by?','bees from flower nectar','hawks from dry grass','fish from river water','蜂蜜由蜜蜂采集花蜜制成。'),Q('honey',2,2,'When someone says “Thanks, honey,” honey may be?','an affectionate way to address someone','a name for a court hearing','a kind of farm tool','honey 可作亲昵称呼。'),Q('honey',3,3,'A honey-colored scarf is likely?','golden yellow or warm amber','dark blue with no warm tones','transparent and colorless','形容词义指蜜黄色。'),Q('honey',4,1,'The word honey can refer to?','a sweet bee product','a type of train delay','a person who lifts cargo','honey 的基本名词义是蜂蜜。')]);
P('honeybee','Honeybee 由 honey 与 bee 组成，指群居、常被饲养以生产蜂蜜并为植物授粉的蜜蜂。',C('honeybee.s1','授粉与生态','A honeybee carried pollen from the apple blossoms to another tree, helping the orchard produce fruit.','一只蜜蜂把花粉从苹果花带到另一棵树上，帮助果园结出果实。','A honeybee carried pollen from the apple blossoms / to another tree / helping the orchard produce fruit.','honeybee 是名词；helping 补充传粉带来的结果。','蜜蜂把花粉带到另一朵花，体现授粉作用。'),M('The honeybee pollinated the flowers by eating every blossom before pollen could move between plants.','The honeybee pollinated the flowers by carrying pollen from one blossom to another.','吃掉花朵并阻止花粉传播不符合授粉行为。'),[Q('honeybee',1,1,'A honeybee is a social bee especially known for?','producing honey and pollinating plants','hunting large mammals','building a paper wasp nest','蜜蜂常被饲养以产蜜并传粉。'),Q('honeybee',2,1,'Why are honeybees important to orchards?','they move pollen between flowers','they cut down fruit trees','they prevent every plant from flowering','蜜蜂传粉可帮助果树结果。'),Q('honeybee',3,1,'A hive may contain?','a colony of honeybees','a herd of horses','a school of hockey players','蜂箱中生活着蜜蜂群体。'),Q('honeybee',4,1,'The compound honeybee names a bee associated with?','honey','a household loan','a newspaper title','词中 honey 指蜂蜜。')]);
P('honeycomb','Honeycomb 由 honey 与 comb 组成，名词指蜜蜂用蜡建造的六边形蜂巢；作动词表示使材料布满小孔或通道。',C('honeycomb.s2','材料结构','Tiny tunnels honeycombed the limestone wall, allowing rainwater to seep through its porous surface.','石灰岩墙布满细小孔道，雨水能从多孔表面渗过去。','Tiny tunnels honeycombed the limestone wall / allowing rainwater to seep through / its porous surface.','honeycomb 作动词表示使某物布满小孔；主语 tunnels 描述形成的结构。','石灰岩内部及表面有许多小孔道，体现动词义。'),M('The bees honeycombed the wall by filling every tiny opening with solid stone.','The bees honeycombed the wall by making many small cavities through it.','填满所有孔洞与“使布满小孔”相反。'),[Q('honeycomb',1,1,'A honeycomb is made of?','wax cells where bees store honey and raise young','wooden panels used for a courtroom floor','a single smooth stone without openings','蜂巢由蜂蜡六边形巢室组成。'),Q('honeycomb',2,2,'To honeycomb a rock is to?','fill it with many small holes or tunnels','polish it until no opening remains','cover it with a layer of honey only','动词 honeycomb 指使布满孔洞。'),Q('honeycomb',3,1,'Why are honeycomb cells often hexagonal?','the shape packs efficiently with shared walls','bees cannot build any other shape','the cells must remain completely round','蜂巢六边形能高效拼接。'),Q('honeycomb',4,2,'A honeycombed wall would likely be?','perforated by many small cavities','perfectly solid and unbroken','covered only by wet paint','墙体有许多空洞符合动词义。')]);
P('honeyed','Honeyed 由 honey 加 -ed 构成，字面可指甜如蜂蜜，也可形容声音、言辞甜美动听，有时暗含刻意讨好的意味。',C('honeyed.s1','声音与修辞','The presenter used a honeyed voice to praise the sponsors, though the audience sensed that the compliment was carefully calculated.','主持人用甜美的声音赞扬赞助商，不过观众察觉这番恭维经过刻意设计。','The presenter used a honeyed voice / to praise the sponsors / though the audience sensed that the compliment was carefully calculated.','honeyed 修饰 voice，表示甜美柔和；though 引出可能的虚情假意。','甜声恭维且带刻意感，体现比喻义。'),M('His honeyed speech sounded harsh and abrasive, with no trace of sweetness or charm.','His honeyed speech sounded smooth and sweet, though it seemed insincere.','粗厉刺耳与 honeyed 的甜美声音相反。'),[Q('honeyed',1,1,'A honeyed voice sounds?','sweet and pleasing','rough and hoarse','silent and impossible to hear','honeyed 可形容甜美声音。'),Q('honeyed',2,1,'Honeyed words may sometimes seem?','overly flattering or insincere','plainly hostile and insulting','strictly scientific','甜言蜜语可能带有讨好意味。'),Q('honeyed',3,1,'A honeyed smell would be?','sweet like honey','sharp like a chemical cleaner','odorless by definition','字面联想是蜂蜜般甜香。'),Q('honeyed',4,1,'Which phrase uses honeyed figuratively?','a honeyed promise meant to win approval','a spoonful of honey in tea','a honeycomb in a beehive','甜美的话语或承诺是比喻用法。')]);
P('honeymoon','Honeymoon 由 honey 与 moon 组合，名词指新婚旅行或新关系初期的和谐阶段，作动词表示去度蜜月。',C('honeymoon.s2','新职务与关系','The new coach’s honeymoon ended after the team lost five games in a row and fans began questioning his choices.','球队连输五场、球迷开始质疑他的决定后，新教练最初受到的宽容期结束了。','The new coach’s honeymoon ended / after the team lost five games in a row / and fans began questioning his choices.','honeymoon 可比喻新职务初期受到的宽容和支持。','最初的支持在持续失利后消退，体现比喻义。'),M('The coach’s honeymoon period began after years in the job, long after supporters had withdrawn their trust.','The coach’s honeymoon period began when he first took the job and supporters welcomed him.','长期任职且已失去支持不符合新任期的初始和谐期。'),[Q('honeymoon',1,1,'A honeymoon is traditionally?','a holiday taken by newly married people','a school assignment due after a break','a trip to inspect a beehive','honeymoon 指新婚旅行。'),Q('honeymoon',2,2,'A new manager’s honeymoon period is?','an initial time of support before criticism grows','the final day after leaving the job','a required annual vacation','比喻义指新职务初期的和谐期。'),Q('honeymoon',3,3,'To honeymoon in Greece means to?','spend a honeymoon there','manage a company’s headquarters there','ask strangers for a free ride there','honeymoon 可作动词表示度蜜月。'),Q('honeymoon',4,2,'Which event might end a political honeymoon?','a new government loses public support after early goodwill','a couple begins their wedding holiday','a new official receives universal support','政治蜜月期会随着批评增多而结束。')]);
P('honk','Honk 是模仿喇叭声的拟声词，可作动词表示按汽车喇叭，也可作名词指喇叭发出的响声。',C('honk.s1','道路交通','The driver honked once to warn a cyclist that the delivery van was turning across the bike lane.','送货车转弯穿过自行车道时，司机按了一声喇叭提醒骑车人。','The driver honked once / to warn a cyclist / that the delivery van was turning across the bike lane.','honk 作动词表示鸣喇叭；to warn 引出鸣笛目的。','司机用车喇叭提醒道路使用者，符合词义。'),M('The driver honked by keeping the car horn completely silent while shouting no warning.','The driver honked once to warn the cyclist before turning.','车喇叭完全无声并未鸣笛。'),[Q('honk',1,1,'A car honks when its driver?','sounds the horn','opens the glove compartment','turns off the engine permanently','honk 作动词表示按喇叭。'),Q('honk',2,1,'A loud honk outside is?','a sound made by a horn','a written traffic ticket','a type of household loan','honk 也可指喇叭声。'),Q('honk',3,1,'Why might a driver honk briefly?','to warn another road user','to make the car move without an engine','to show that the vehicle has no horn','短鸣喇叭可用于警示。'),Q('honk',4,1,'The word honk imitates?','the sound of a horn','the sound of a silent page','the taste of honey','honk 是拟声词。')]);
P('honor','Honor 源自拉丁语 honor，名词可指荣誉、荣幸或对人的尊敬；作动词可表彰某人，也可表示按期兑现支票或承诺。',C('honor.s4','金融与支付','The bank honored the cheque when it was presented on the due date and the account had sufficient funds.','支票在到期日提示付款且账户资金充足时，银行按期予以兑现。','The bank honored the cheque / when it was presented on the due date / and the account had sufficient funds.','honor 在金融语境中表示按期兑付支票或票据。','银行在到期日完成付款，体现 s4。'),M('The bank honored the cheque by refusing payment even though the account held enough funds.','The bank honored the cheque by paying it when presented.','有充足资金却拒绝付款，不是兑付支票。'),[Q('honor',1,1,'It is an honor to meet someone means it is?','a privilege that brings respect or pleasure','a routine delay on a road','an unwanted household chore','honor 名词可指荣幸。'),Q('honor',2,2,'To show honor to a scientist is to?','treat the scientist with respect','hide the scientist’s work','charge the scientist a late fee','名词 honor 也指尊敬。'),Q('honor',3,3,'A school may honor a graduate by?','giving an award or public recognition','withholding every certificate','canceling the graduation ceremony','honor 作动词可表示表彰。'),Q('honor',4,4,'A bank honors a cheque when it?','accepts and pays it when due','prints it but refuses payment','uses it as a household receipt','金融义指按期兑现。')]);
P('honorable','Honorable 由 honor 加 -able 构成，形容符合道德原则、正直体面或值得尊敬的行为与人。',C('honorable.s1','职业操守','The mediator proposed an honorable settlement that admitted the harm, repaid the costs, and treated both sides fairly.','调解员提出一项正当体面的和解方案：承认造成的伤害、偿还费用并公平对待双方。','The mediator proposed an honorable settlement / that admitted the harm, repaid the costs, / and treated both sides fairly.','honorable 修饰 settlement，强调正直、公平且值得尊重。','承认责任并公平补偿体现道德正直。'),M('The committee called the dishonest cover-up honorable because it hid the harm from everyone affected.','The committee called the honest disclosure and fair repayment honorable.','掩盖伤害是不诚实的，不符合 honorable。'),[Q('honorable',1,1,'An honorable action is?','morally right and worthy of respect','deliberately dishonest for personal gain','unrelated to any ethical choice','honorable 指正直、值得尊敬。'),Q('honorable',2,1,'Which choice is honorable?','admitting a mistake and making fair repairs','blaming an innocent coworker to avoid trouble','hiding evidence from people affected','承担责任并补救体现正直。'),Q('honorable',3,1,'An honorable person is guided by?','strong moral principles','a desire to deceive everyone','a rule to avoid all commitments','honorable 描写遵循道德原则的人。'),Q('honorable',4,1,'The suffix -able in honorable suggests?','worthy of or capable of receiving honor','without any connection to respect','the person who gives an award','-able 表示值得受到尊敬。')]);

})();
